      '@keyframes kpv-sweet-grid{from{background-position:0 0,0 0}to{background-position:50px 32px,50px 32px}}@keyframes kpv-sweet-scallop{from{background-position:0 0}to{background-position:80px 0}}@keyframes kpv-sweet-circle{0%,100%{transform:translate(-50%,-50%) scale(.94);box-shadow:0 0 0 2px rgba(255,255,255,.16),0 0 30px rgba(236,191,192,.2)}50%{transform:translate(-50%,-50%) scale(1.04);box-shadow:0 0 0 7px rgba(255,255,255,.16),0 0 62px rgba(236,191,192,.46)}}',
