const SCENES = ['poster', 'split', 'stack', 'impact', 'orbit'];
const PV_ACTS = ['intro', 'rise', 'peak', 'outro'];
const PV_PREVIEW_LYRICS = [
  { id: 'pv-preview-0', time: 0, duration: 3.2, text: 'WORDS BREATHE', translation: 'WORDS BREATHE WITH THE BEAT' },
  { id: 'pv-preview-1', time: 3.2, duration: 3.5, text: 'CUT THROUGH', translation: 'CUT THROUGH THE NIGHT' },
  { id: 'pv-preview-2', time: 6.7, duration: 3.4, text: 'LET LIGHT FALL', translation: 'LET THE LIGHT FALL' },
  { id: 'pv-preview-3', time: 10.1, duration: 3.7, text: 'SOUND FIELD', translation: 'THE SOUND FIELD TURNS' },
  { id: 'pv-preview-4', time: 13.8, duration: 4.1, text: 'YOUR PV', translation: 'THIS IS YOUR PV' }
];
const PV_PREVIEW_CYCLE = PV_PREVIEW_LYRICS[PV_PREVIEW_LYRICS.length - 1].time
  + PV_PREVIEW_LYRICS[PV_PREVIEW_LYRICS.length - 1].duration;
const AUTO_CHOREOGRAPHIES = [
  ['poster', 'split', 'impact', 'orbit', 'stack'],
  ['poster', 'stack', 'orbit', 'split', 'impact'],
  ['poster', 'orbit', 'split', 'stack', 'impact'],
  ['poster', 'impact', 'split', 'orbit', 'stack'],
  ['poster', 'stack', 'impact', 'split', 'orbit']
];
const clamp = (value, min = 0, max = 1) => Math.min(max, Math.max(min, value));

// The low-frequency lyric engine index can be one frame behind the media
// clock (especially during a seek or when a line has a very short duration).
// KTV uses a second, visual index derived from the same clock so the line that
// is actually being heard never remains in the bottom "NEXT LINE" slot.
function resolveVisualActiveIndex(lines = [], currentTime = 0, fallback = -1) {
  if (!lines.length) return -1;
  const time = Number.isFinite(Number(currentTime)) ? Number(currentTime) : 0;
  const target = time + 0.035;
  let low = 0;
  let high = lines.length - 1;
  let resolved = -1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    if (Number(lines[middle]?.time || 0) <= target) {
      resolved = middle;
      low = middle + 1;
    } else {
      high = middle - 1;
    }
  }
  if (resolved >= 0) return resolved;
  return fallback >= 0 && fallback < lines.length ? fallback : 0;
}

function findNextVisualBoundaryIndex(lines = [], currentTime = 0) {
  const target = Number(currentTime) + 0.035;
  let low = 0;
  let high = lines.length - 1;
  let result = -1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    if (Number(lines[middle]?.time || 0) > target) {
      result = middle;
      high = middle - 1;
    } else {
      low = middle + 1;
    }
  }
  return result;
}

function resolveSongAct(index, total) {
  if (total <= 1) return 'intro';
  const progress = index / Math.max(1, total - 1);
  if (progress < 0.16) return 'intro';
  if (progress < 0.52) return 'rise';
  if (progress < 0.83) return 'peak';
  return 'outro';
}

function resolveRenderQuality(config = {}, runtimeOverride = null) {
  const requested = config.ktvRenderQuality || 'auto';
  if (requested === 'rich' || requested === 'balanced' || requested === 'efficient') return requested;
  // Auto has a one-way runtime escape hatch. Device memory/CPU figures do not
  // capture 4K compositor load, driver contention or a busy Electron window;
  // sustained missed frames therefore prefer a stable efficient scene for the
  // rest of the current track instead of repeatedly stuttering and recovering.
  if (runtimeOverride === 'efficient') return 'efficient';
  const memory = typeof navigator === 'undefined' ? 0 : Number(navigator.deviceMemory || 0);
  const cores = typeof navigator === 'undefined' ? 0 : Number(navigator.hardwareConcurrency || 0);
  // Keep Auto on the balanced path. Rich mode is still available explicitly,
  // but long word-timed songs should not assume that a desktop GPU can carry
  // every blur, blend layer and glyph at once.
  if ((memory > 0 && memory <= 4) || (cores > 0 && cores <= 4)) return 'efficient';
  // Auto should favour steady frame delivery on laptops and integrated GPUs.
  // Rich remains an explicit opt-in, so normal PV playback does not pay for
  // extra blur/blend layers merely because the machine reports high memory.
  return 'balanced';
}

// These are deliberately opinionated rather than a pile of low-level knobs.
// A text PV needs a coherent art direction across an entire song, so each
// preset owns its palette, typography treatment and overlay language.
