const CARD_BOARD_PRESETS = new Set(['blue-structure', 'cyber-grunge', 'kawaii-pixel', 'crime-scene']);
const EAST_ASIAN_ABSOLUTE_LAYOUTS = new Set(['vertical-columns', 'blue-cards', 'grunge-cards', 'impact-scatter']);

function getLineRhythm(line, tokens = []) {
  const visible = tokens.filter(token => String(token?.text || '').trim());
  const compactText = String(line?.text || '').replace(/\s+/g, '');
  const duration = Math.max(0.1, Number(line?.duration) || 0);
  const isLatinPhrase = !isEastAsianText(line?.text) && /[a-z]/i.test(String(line?.text || ''));
  if (visible.length <= 3 || compactText.length <= 3) return 'emblem';
  if (isLatinPhrase && visible.length <= 8) return 'ticker';
  if (visible.length >= 15 || compactText.length >= 15 || duration >= 7) return 'quote';
  if (duration > 0.1 && visible.length / duration >= 5.6) return 'rush';
  return 'phrase';
}

function normalizeRoleText(value) {
  return String(value || '').replace(/[\s\p{P}]/gu, '').toLowerCase();
}

function resolveLineRole(line, index, lines = [], occurrenceMap = null) {
  const text = normalizeRoleText(line?.text);
  if (!text) return 'verse';
  const occurrences = occurrenceMap?.get(text) ?? lines.reduce((count, current) => (
    normalizeRoleText(current?.text) === text ? count + 1 : count
  ), 0);
  if (text.length >= 2 && occurrences >= 2) return 'hook';
  if (index > 0 && text.length <= 3) return 'hit';
  return 'verse';
}

// A template is kept for an entire song, while each lyric line still receives
// a distinct shot inside that template's visual language. Lyrics' own length
// and speed also select a shot grammar, preventing the same row layout from
// repeating through an entire verse.
function resolveLineGrammar(config, preset, scene, line, tokens, role = 'verse') {
  const selectedEffect = config?.ktvTextEffect || 'auto';
  const selectedLayout = PRESET_LAYOUTS[preset] || 'cinema-hero';
  const followsTemplate = selectedEffect === 'auto'
    || selectedEffect === 'template'
    || selectedEffect === 'template-rich'
    || selectedEffect === 'template-single';
  const manualEffect = !followsTemplate;
  const rhythm = getLineRhythm(line, tokens);
  let effect = manualEffect ? selectedEffect : (PRESET_TEXT_EFFECTS[preset] || 'slice');
  let layout = selectedLayout;

  if (!manualEffect) {
    if (scene === 'split') effect = preset === 'matrix' || preset === 'night-city' ? 'terminal' : 'slash';
    if (scene === 'impact') effect = preset === 'hysteric-night' ? 'shatter' : preset === 'p5' ? 'glitch' : preset === 'blue-impact' ? 'burst' : 'scatter';
    if (scene === 'orbit') effect = preset === 'girly-clouds' || preset === 'haruhikage' ? 'float' : 'orbit';
    if (scene === 'stack') effect = CARD_BOARD_PRESETS.has(preset) ? 'cards' : 'stagger';
    if (rhythm === 'rush' && scene !== 'impact') effect = preset === 'matrix' || preset === 'night-city' ? 'terminal' : 'slice';
    if (role === 'hook') effect = preset === 'emotion-cinema' ? 'fade' : preset === 'matrix' ? 'glitch' : 'stamp';
  }

  if (CARD_BOARD_PRESETS.has(preset)) {
    if (scene === 'split') layout = 'split-hero';
    if (scene === 'stack') layout = 'vertical-columns';
    if (scene === 'impact') layout = 'impact-scatter';
    if (scene === 'orbit') layout = 'orbit-board';
  } else {
    // Keep the preset's structural layout for non-card templates. The old
    // rhythm fallback replaced cinema, terminal, orbit and split compositions
    // with the same emblem/ticker/quote boards, which made every PV converge
    // to one visual language on longer lyrics. Rhythm still changes the text
    // effect above; the selected template owns the composition.
  }
  if (role === 'hook' && CARD_BOARD_PRESETS.has(preset)) layout = 'impact-scatter';
  // East-Asian lyric phrases must remain readable in normal writing order.
  // The card-board layouts are attractive for Latin glyphs, but placing every
  // CJK glyph in an absolute grid turns a Japanese sentence into a vertical
  // column of unrelated characters. Phrase units are still animated, just in
  // a horizontal line.
  // Matrix keeps its own terminal board even for CJK: it is a horizontal
  // console readout with one active character cell, never the generic phrase row.
  if (preset === 'matrix') layout = 'matrix-terminal';
  else if (isEastAsianText(line?.text)) layout = 'jp-phrase';
  const motionVariant = resolveTemplateMotionVariant(preset, scene, rhythm, role, Number(line?.time) || 0, line);
  return { effect, layout, rhythm, motionVariant };
}

function resolveTemplateMotionVariant(preset, scene, rhythm, role, index, line) {
  const variants = PRESET_MOTION_VARIANTS[preset] || PRESET_MOTION_VARIANTS.custom;
  // Template identity is the primary choice; line content, shot and chorus role
  // rotate it deterministically so consecutive sentences do not replay the
  // same entrance while revisiting a song remains visually stable.
  const seed = hashText([preset, scene, rhythm, role, index, line?.text || ''].join('|'));
  if (role === 'hook') return variants[(seed + 1) % variants.length];
  if (rhythm === 'rush') return variants[(seed + 2) % variants.length];
  return variants[seed % variants.length];
}

function resolveWordVariant(config, preset, motionVariant, index, line) {
  const variants = PRESET_WORD_VARIANTS[preset] || PRESET_WORD_VARIANTS.custom;
  const selected = config?.ktvTextEffect || 'auto';
  if (selected === 'template-single') return variants[0];
  const seed = hashText([preset, motionVariant, index, line?.text || ''].join('|'));
  return variants[seed % variants.length];
}

// Keep the template's identity while allowing individual glyphs to use a
// nearby treatment. The seed is stable, so seeking/reopening a song does not
// reshuffle the whole stage, but neighbouring glyphs still avoid a mechanical
// one-animation sweep.
function resolveTokenWordVariant(config, preset, lineVariant, token, tokenIndex, tokenCount, lineIndex, role = 'verse', previousVariant = '') {
  const variants = PRESET_WORD_VARIANTS[preset] || PRESET_WORD_VARIANTS.custom;
  if (variants.length < 2) return lineVariant;
  const mode = config?.ktvTextEffect || 'auto';
  if (mode === 'template-single') return lineVariant;
  const randomness = mode === 'template-rich' ? 'max' : 'rich';

  const seed = hashText([
    preset,
    lineVariant,
    lineIndex,
    tokenIndex,
    token?.text || ''
  ].join('|'));
  const primaryIndex = Math.max(0, variants.indexOf(lineVariant));
  const alternateIndex = (primaryIndex + 1 + (seed % Math.max(1, variants.length - 1))) % variants.length;
  const accentIndex = (primaryIndex + 2) % variants.length;
  const isBoundary = tokenIndex === 0 || tokenIndex === tokenCount - 1;
  const isPunctuation = /^[\s\p{P}\p{S}]+$/u.test(String(token?.text || ''));
  const isEmphasis = role === 'hook' || isBoundary || isPunctuation;
  const avoidRepeats = config?.ktvAvoidWordRepeats !== false;

  let selectedIndex = primaryIndex;
  if (randomness === 'max') {
    selectedIndex = isEmphasis && seed % 3 === 0 ? accentIndex : seed % 100 < 62 ? primaryIndex : seed % 2 ? alternateIndex : accentIndex;
  } else if (randomness === 'rich') {
    selectedIndex = isEmphasis && seed % 4 === 0 ? accentIndex : seed % 100 < 70 ? primaryIndex : alternateIndex;
  } else if (randomness === 'subtle') {
    selectedIndex = seed % 100 < 84 ? primaryIndex : alternateIndex;
  }

  let result = variants[selectedIndex] || lineVariant;
  if (avoidRepeats && result === previousVariant) {
    result = variants[(selectedIndex + 1) % variants.length] || result;
  }
  return result;
}

function resolveFlySpatialPoint(distance = 0, lineIndex = 0, text = '') {
  if (distance === 0) return { x: 0, y: 0, z: 80, rotation: 0, scale: 1 };
  const anchors = {
    '-2': { x: -27, y: -15, z: -420, rotation: -6, scale: .76 },
    '-1': { x: 24, y: -10, z: -230, rotation: 4, scale: .86 },
    '1': { x: -22, y: 15, z: -260, rotation: -4, scale: .84 },
    '2': { x: 27, y: 12, z: -430, rotation: 6, scale: .74 }
  };
  const base = anchors[String(distance)] || anchors[distance < 0 ? '-1' : '1'];
  const seed = hashText(['fly-space', lineIndex, text].join('|'));
  return {
    x: base.x + ((seed % 7) - 3) * .55,
    y: base.y + ((Math.floor(seed / 7) % 7) - 3) * .42,
    z: base.z - (seed % 5) * 9,
    rotation: base.rotation + ((seed % 5) - 2) * .35,
    scale: base.scale
  };
}

function getAdaptiveSlot(index, count, layout) {
  const isImpact = layout === 'impact-scatter';
  const isCardBoard = layout === 'blue-cards' || layout === 'grunge-cards';
  const isVerticalColumns = layout === 'vertical-columns';
  // Character cards need a horizontal editorial rhythm. A square-root grid
  // turns Japanese lyrics into four tall, unrelated columns; instead compose
  // them as a compact 2-3 row collage in the central safe area.
  const columns = isVerticalColumns
    ? Math.max(1, Math.min(5, Math.ceil(count / Math.min(4, Math.max(2, Math.ceil(count / 4))))) )
    : isCardBoard
    ? Math.max(1, Math.min(count, count <= 5 ? count : count <= 10 ? 5 : 6))
    : Math.max(1, Math.min(count, Math.ceil(Math.sqrt(count * (isImpact ? 1.28 : 1.06)))));
  const rows = Math.max(1, Math.ceil(count / columns));
  const column = isVerticalColumns ? Math.floor(index / rows) : index % columns;
  const row = isVerticalColumns ? index % rows : Math.floor(index / columns);
  const horizontalSpan = isVerticalColumns ? (columns <= 2 ? 42 : columns <= 3 ? 56 : 66) : isCardBoard ? (columns <= 3 ? 48 : 64) : 76;
  const verticalSpan = isVerticalColumns ? (rows === 1 ? 0 : Math.min(66, 31 + (rows - 1) * 12)) : isCardBoard ? (rows === 1 ? 0 : Math.min(42, 22 + (rows - 1) * 11)) : 54;
  const x = columns === 1 ? 50 : 50 + ((column / (columns - 1)) - 0.5) * horizontalSpan;
  const y = rows === 1 ? 50 : 50 + ((row / (rows - 1)) - 0.5) * verticalSpan;
  // Deterministic micro-offsets retain a hand-cut frame feel while every card
  // keeps its own non-overlapping cell, including long CJK lines.
  const jitterX = isImpact ? ((index * 17) % 5 - 2) * 2.4 : ((index * 11) % 3 - 1) * (isVerticalColumns ? 0.55 : isCardBoard ? 0.9 : 1.2);
  const jitterY = isImpact ? ((index * 23) % 5 - 2) * 2.1 : ((index * 7) % 3 - 1) * (isVerticalColumns ? 0.6 : isCardBoard ? 0.8 : 1);
  const rotation = (isImpact ? ((index * 13) % 7 - 3) : ((index * 5) % 5 - 2)) * (isImpact ? 2.2 : 1.1);
  const density = count > 18 ? 0.64 : count > 13 ? 0.72 : count > 9 ? 0.82 : count > 6 ? 0.91 : 1;
  return [x + jitterX, y + jitterY, rotation, density * (isImpact ? 1.04 : 1)];
}

function getTokenVisualScale(token, index, layout = '') {
  const compact = String(token?.text || '').replace(/\s+/gu, '');
  const isLatinWord = token?.kind === 'word' && /^[\p{Script=Latin}\p{N}'’_-]+$/u.test(compact);
  const isAbsolute = ['blue-cards', 'grunge-cards', 'impact-scatter', 'vertical-columns', 'orbit-board'].includes(layout);
  const isEditorial = ['jp-phrase', 'cinema-hero', 'terminal-board', 'split-hero', 'outline-hero', 'stagger-board'].includes(layout);
  if ((!isAbsolute && !isEditorial) || !compact) return 1;
  if (isLatinWord) return isAbsolute ? [1, .98, 1.04, .97, 1.02, .99][index % 6] : 1;
  const wordScale = token?.kind === 'word' ? Math.min(1, 4.6 / Math.max(1, compact.length)) : 1;
  const editorialScale = isAbsolute
    ? [1, .86, 1.14, .94, 1.08, .9][index % 6]
    : [1, .94, 1.08, .98, 1.04, .92][index % 6];
  return Math.max(.62, Math.min(1.18, wordScale * editorialScale));
}

// A PV template should change the typographic rhythm, not only the paint
// colour. These small deterministic scales create the unequal type sizes
// used by kinetic-typography posters while keeping long words readable.
function getPresetTokenScale(preset, index, token, count = 1) {
  const compact = String(token?.text || '').replace(/\s+/gu, '');
  const isLatinWord = token?.kind === 'word' && /^[\p{Script=Latin}\p{N}'’_-]+$/u.test(compact);
  const wordPenalty = isLatinWord ? 1 : token?.kind === 'word' ? Math.min(1, 5 / Math.max(1, compact.length)) : 1;
  const rhythms = {
    'blue-impact': [1.18, .82, 1.04, .72, 1.28, .9],
    'kinetic-split': [1.16, .78, 1.1, .88, 1.24, .8],
    'blue-structure': [1, .84, 1.18, .92, 1.08, .78],
    'cyber-grunge': [1.08, .72, 1.22, .86, .96, .68],
    geometric: [1.12, .86, 1.04, .78, 1.16, .9],
    matrix: [.92, 1.18, .76, 1.06, .82, 1.24],
    'night-city': [1.16, .8, 1.08, .92, 1.2, .76],
    'emotion-cinema': [1.08, .88, 1.22, .94, 1.14, .82],
    'hysteric-night': [1.22, .74, 1.08, .68, 1.3, .86],
    'spider-web': [.84, 1.16, .9, 1.22, .78, 1.04],
    'staggered-text': [1.16, .82, .98, 1.1, .76, 1.24],
    'calm-villain': [.92, 1.08, .84, 1.16, .9, 1.02],
    'girly-clouds': [1.08, .92, 1.16, .86, 1.2, .96],
    'sweet-pink': [1.12, .82, 1.2, .9, 1.04, .78],
    'fly-me-to-the-moon': [1.18, .86, 1.04, .94, 1.2, .8],
    'kawaii-pixel': [1.04, .76, 1.22, .84, 1.16, .7],
    'crime-scene': [1.24, .8, 1.08, .72, 1.18, .9],
    haruhikage: [1.16, .9, 1.24, .82, 1.06, .94],
    custom: [1, .9, 1.08, .94, 1.12, .86],
    p5: [1.22, .78, 1.1, .72, 1.28, .86],
    'paper-cut': [1.1, .88, 1.18, .92, 1.04, .8]
  };
  const rhythm = isLatinWord ? [1, .97, 1.04, .98, 1.02, .95] : (rhythms[preset] || rhythms.custom);
  const density = count > 14 ? .92 : count > 9 ? .96 : 1;
  return Math.max(.64, Math.min(1.28, rhythm[index % rhythm.length] * wordPenalty * density));
}

function getThemeUnitPlacement(preset, scene, index, total) {
  const lanes = {
    'blue-structure': [['6%', '34%'], ['7%', '68%'], ['23%', '18%'], ['72%', '40%'], ['70%', '78%'], ['42%', '12%']],
    'cyber-grunge': [['72%', '20%'], ['7%', '62%'], ['62%', '76%'], ['18%', '23%'], ['78%', '49%'], ['32%', '78%']],
    matrix: [['22%', '16%'], ['72%', '22%'], ['18%', '72%'], ['80%', '68%'], ['34%', '14%'], ['62%', '80%']],
    'emotion-cinema': [['70%', '19%'], ['8%', '70%'], ['65%', '76%'], ['30%', '18%'], ['78%', '52%'], ['18%', '34%']],
    'girly-clouds': [['6%', '22%'], ['72%', '46%'], ['8%', '72%'], ['76%', '20%'], ['44%', '76%'], ['28%', '15%']],
    'sweet-pink': [['72%', '18%'], ['8%', '64%'], ['66%', '74%'], ['18%', '26%'], ['78%', '48%'], ['38%', '14%']],
    'kawaii-pixel': [['8%', '24%'], ['72%', '52%'], ['10%', '74%'], ['76%', '18%'], ['44%', '76%'], ['28%', '18%']],
    haruhikage: [['72%', '18%'], ['8%', '68%'], ['66%', '76%'], ['20%', '22%'], ['78%', '48%'], ['38%', '14%']],
    'hysteric-night': [['70%', '20%'], ['8%', '68%'], ['72%', '76%'], ['18%', '26%'], ['78%', '48%'], ['36%', '14%']]
  };
  const selected = lanes[preset] || [['72%', '18%'], ['8%', '68%'], ['70%', '76%'], ['18%', '24%'], ['78%', '48%'], ['38%', '14%']];
  const [x, y] = selected[index % selected.length];
  const rotation = ((index * 17 + total * 3) % 9) - 4;
  const scale = total > 4 ? (index % 3 === 1 ? .78 : index % 3 === 2 ? .9 : 1) : (index % 2 ? .86 : 1);
  const splitShift = scene === 'split' ? (index % 2 ? 4 : -4) : scene === 'impact' ? (index % 2 ? -3 : 3) : 0;
  return {
    left: `calc(${x} + ${splitShift}%)`,
    top: y,
    right: 'auto',
    bottom: 'auto',
    maxWidth: total > 3 ? '22%' : '28%',
    fontSize: `calc(clamp(15px, 2vw, 30px) * ${scale})`,
    transform: `rotate(${rotation}deg)`
  };
}

// Absolute card compositions have a finite safe grid. Instead of shrinking a
// 30+ character lyric until it collides or becomes unreadable, merge adjacent
// timed glyphs into compact lyric blocks. Each block keeps its first/last
// timing so the KTV sweep remains musically correct.
function condenseCompositionTokens(tokens = [], layout, renderQuality = 'balanced') {
  const isAbsoluteComposition = ['blue-cards', 'grunge-cards', 'impact-scatter', 'vertical-columns'].includes(layout);
  const maxTiles = isAbsoluteComposition
    ? (layout === 'impact-scatter' ? 18 : 15)
    : renderQuality === 'efficient' ? 20 : renderQuality === 'balanced' ? 32 : 48;
  if (tokens.length <= maxTiles) return tokens;
  const groupSize = Math.ceil(tokens.length / maxTiles);
  const groups = [];
  for (let offset = 0; offset < tokens.length; offset += groupSize) {
    const slice = tokens.slice(offset, offset + groupSize);
    groups.push({
      key: `block-${slice.map(token => token.key).join('-')}`,
      text: slice.map(token => token.text).join(''),
      start: slice[0].start,
      end: slice[slice.length - 1].end,
      // Preserve choreography timing when a long line is condensed into
      // layout blocks. Plain LRC intentionally gives every token one
      // line-level landing window; dropping it here would recreate a
      // left-to-right block sweep only in card layouts.
      revealStart: slice[0].revealStart ?? slice[0].start,
      revealEnd: slice[slice.length - 1].revealEnd ?? slice[slice.length - 1].end,
      revealGroup: slice[0].revealGroup ?? 0,
      kind: slice.some(token => token.kind === 'word') ? 'word' : 'grapheme'
    });
  }
  return groups;
}

function lineKey(line, index, trackKey = '') {
  return `${trackKey || 'track'}:${line?.id ?? line?.time ?? 'line'}-${index}`;
}

function isWordLike(value) {
  return /[\p{Script=Latin}\p{N}]/u.test(String(value || '')) && !/[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]/u.test(String(value || ''));
}

function getLineEnd(line, nextLine) {
  const start = Number(line?.time) || 0;
  const declared = Number(line?.duration);
  if (Number.isFinite(declared) && declared > 0.06) return start + declared;
  const next = Number(nextLine?.time);
  if (Number.isFinite(next) && next > start + 0.06) return next;
  return start + 4.2;
}

function isSectionStart(index, lines = []) {
  if (index <= 0) return true;
  const previous = lines[index - 1];
  const previousEnd = getLineEnd(previous, lines[index]);
  return (Number(lines[index]?.time) || 0) - previousEnd >= 2.2;
}

// AMLL/TTML words are not guaranteed for every provider.  This keeps the KTV
// sweep useful with plain LRC too, while preserving precise word timings when
// they are available.
function buildTokens(line, nextLine) {
  const start = Number(line?.time) || 0;
  const end = getLineEnd(line, nextLine);
  // Latin runs are kept as readable words, while East-Asian scripts retain
  // their character rhythm. This prevents `hello world` from becoming
  // `h/e/l/l/o/ /w/o/r/l/d` without turning mixed Japanese/English lines into
  // one oversized card.
  const toUnits = (text) => segmentMixedTokens(text || '').filter(unit => unit.text.length > 0);
  const fallback = (text) => {
    const units = toUnits(text);
    const duration = Math.max(0.25, end - start);
    return units.map((unit, index) => ({
      text: unit.text,
      kind: unit.kind,
      start: start + (duration * index) / Math.max(1, units.length),
      end: start + (duration * (index + 1)) / Math.max(1, units.length),
      // Plain LRC fallback tokens used to have an undefined React key. That
      // made React reuse the wrong glyph node when a lyric line changed and
      // could leave stale fill/state attributes behind.
      key: `fallback-${index}`
    }));
  };

  if (!Array.isArray(line?.words) || line.words.length === 0) return fallback(line?.text);

  const timedUnits = [];
  line.words.forEach((word) => {
    const text = String(word?.text ?? '');
    if (!text) return;
    const wordStart = Number(word?.startSec ?? word?.startTime);
    const wordEnd = Number(word?.endSec ?? word?.endTime);
    const duration = Number(word?.durationSec);
    const safeStart = Number.isFinite(wordStart) ? wordStart : start;
    const safeEnd = Number.isFinite(wordEnd) && wordEnd > safeStart
      ? wordEnd
      : safeStart + Math.max(0.06, Number.isFinite(duration) ? duration : (end - start) / line.words.length);
    timedUnits.push({ text, kind: toUnits(text).some(unit => unit.kind === 'word') ? 'word' : 'grapheme', start: safeStart, end: safeEnd });
  });
  const merged = mergeTimedMixedTokens(line?.text || '', timedUnits, start, end);
  return merged.length
    ? merged.map((token, index) => ({ ...token, key: `${index}-${token.text}-${token.start}` }))
    : fallback(line?.text);
}

function normalizePhraseChunk(tokens = [], indexes = []) {
  return indexes.map(index => String(tokens[index]?.text || '').replace(/[\s\p{P}]/gu, '').toLowerCase()).join('');
}

function resolveRevealMode(config, line, tokens = [], index = 0, role = 'verse', preset = 'custom') {
  const selected = config?.ktvTextEffect || 'auto';
  // The Matrix template is a terminal stream: retain true per-token timing
  // even for compact lines so its cursor cell can travel through the lyric.
  const followsTemplate = selected === 'auto'
    || selected === 'template'
    || selected === 'template-rich'
    || selected === 'template-single';
  if (preset === 'matrix' && followsTemplate) return 'letter';
  if (selected === 'phrase') return 'phrase';
  if (selected === 'scan') return 'scan';
  if (!followsTemplate) return 'letter';

  const visibleCount = tokens.filter(token => String(token?.text || '').trim()).length;
  const inferredDuration = tokens.length
    ? Math.max(0, Number(tokens[tokens.length - 1]?.end) - (Number(line?.time) || 0))
    : 0;
  const duration = Math.max(0.1, Number(line?.duration) || inferredDuration);
  const compactLength = tokens
    .map(token => String(token?.text || '').replace(/[\s\p{P}\p{S}]/gu, ''))
    .join('').length;
  // Short lines are easier to read as one landing card. Longer lines keep
  // the default per-glyph reveal, including plain LRC without word timing.
  if (duration <= 1.35 || visibleCount <= 3 || compactLength <= 4) return 'phrase';

  // Repeated material is the one deliberate exception: the phrase
  // choreography can land repeated groups together without changing normal
  // lines into block reveals.
  if (visibleCount >= 4) {
    for (const repeats of [3, 2]) {
      if (visibleCount % repeats !== 0) continue;
      const chunkSize = visibleCount / repeats;
      const signatures = Array.from({ length: repeats }, (_, repeatIndex) => {
        const offset = repeatIndex * chunkSize;
        return tokens.slice(offset, offset + chunkSize)
          .map(token => String(token?.text || '').replace(/[\s\p{P}\p{S}]/gu, '').toLowerCase())
          .join('');
      });
      if (signatures[0] && signatures.every(signature => signature === signatures[0])) return 'phrase';
    }
  }
  return 'letter';
}

// KTV should reveal a phrase, not mechanically type every glyph. Short lines
// land as one visual unit, long lines use a few phrase blocks, and repeated
// chunks such as "abc abc" are split into synchronized groups: the first abc
// appears together, then the second abc appears together.
function applyTokenChoreography(line, tokens = [], revealMode = 'phrase') {
  if (!tokens.length) return tokens;
  const start = Number(line?.time) || Number(tokens[0]?.start) || 0;
  const tokenEnd = tokens.reduce((latest, token) => {
    const end = Number(token?.end);
    return Number.isFinite(end) ? Math.max(latest, end) : latest;
  }, start);
  const hasDeclaredDuration = Number(line?.duration) > 0.06;
  // Providers often omit line.duration while still giving us the next-line
  // boundary or word timings. Falling back to getLineEnd(line, null) here
  // would inject 4.2 seconds and stretch short phrases past their vocal hit.
  const declaredEnd = hasDeclaredDuration
    ? getLineEnd(line, null)
    : Math.max(start + 0.08, tokenEnd);
  const duration = Math.max(0.08, declaredEnd - start);
  if ((!Array.isArray(line?.words) || line.words.length === 0) && revealMode !== 'letter') {
    const landEnd = start + Math.min(0.42, Math.max(0.16, duration * 0.18));
    return tokens.map(token => ({
      ...token,
      revealGroup: 0,
      revealStart: start,
      revealEnd: landEnd
    }));
  }
  if (revealMode === 'letter') {
    return tokens.map((token, tokenIndex) => ({
      ...token,
      revealGroup: tokenIndex,
      revealStart: Number.isFinite(Number(token.start)) ? Number(token.start) : start,
      revealEnd: Number.isFinite(Number(token.end)) ? Number(token.end) : start + duration
    }));
  }
  if (revealMode === 'scan') {
    const scanEnd = start + Math.min(1.35, Math.max(0.42, duration * 0.38));
    return tokens.map(token => ({ ...token, revealGroup: 0, revealStart: start, revealEnd: scanEnd }));
  }
  const visibleIndexes = tokens
    .map((token, index) => String(token?.text || '').trim() ? index : -1)
    .filter(index => index >= 0);
  const visibleCount = visibleIndexes.length;
  const groupByIndex = new Map();
  let groupCount = 1;

  let repeatedPhrase = false;
  // Detect repeated word chunks before the short-line fast path. Latin words
  // are intentionally kept as one token, so "abc abc" has only two visible
  // tokens and must still become two synchronized phrase shots.
  if (visibleCount >= 2) {
    for (const repeats of [3, 2]) {
      if (visibleCount % repeats !== 0) continue;
      const chunkSize = visibleCount / repeats;
      if (chunkSize < 1) continue;
      const signatures = Array.from({ length: repeats }, (_, repeatIndex) => {
        const chunk = visibleIndexes.slice(repeatIndex * chunkSize, (repeatIndex + 1) * chunkSize);
        return normalizePhraseChunk(tokens, chunk);
      });
      if (signatures[0] && signatures.every(signature => signature === signatures[0])) {
        groupCount = repeats;
        repeatedPhrase = true;
        visibleIndexes.forEach((tokenIndex, visibleIndex) => {
          groupByIndex.set(tokenIndex, Math.floor(visibleIndex / chunkSize));
        });
        break;
      }
    }
  }

  const shouldLandInstantly = !repeatedPhrase && (duration <= 1.45 || visibleCount <= 3);

  if (groupByIndex.size === 0 && !shouldLandInstantly) {
    groupCount = Math.min(4, Math.max(2, Math.ceil(visibleCount / 4)));
    const chunkSize = Math.ceil(visibleCount / groupCount);
    visibleIndexes.forEach((tokenIndex, visibleIndex) => {
      groupByIndex.set(tokenIndex, Math.min(groupCount - 1, Math.floor(visibleIndex / chunkSize)));
    });
  }
  tokens.forEach((_, tokenIndex) => {
    if (!groupByIndex.has(tokenIndex)) groupByIndex.set(tokenIndex, 0);
  });
  if (shouldLandInstantly) groupCount = 1;

  const spans = Array.from({ length: groupCount }, () => ({ start: Infinity, end: -Infinity }));
  tokens.forEach((token, tokenIndex) => {
    const group = groupByIndex.get(tokenIndex) || 0;
    const tokenStart = Number.isFinite(Number(token.start)) ? Number(token.start) : start;
    const tokenEnd = Number.isFinite(Number(token.end)) ? Number(token.end) : tokenStart + duration;
    spans[group].start = Math.min(spans[group].start, tokenStart);
    spans[group].end = Math.max(spans[group].end, tokenEnd);
  });
  if (shouldLandInstantly) {
    spans[0] = { start, end: start + Math.min(0.34, Math.max(0.12, duration * 0.34)) };
  }
  return tokens.map((token, tokenIndex) => {
    const revealGroup = groupByIndex.get(tokenIndex) || 0;
    const span = spans[revealGroup];
    return {
      ...token,
      revealGroup,
      revealStart: Number.isFinite(span.start) ? span.start : start,
      revealEnd: Number.isFinite(span.end) && span.end > span.start ? span.end : start + duration
    };
  });
}

function resolveChoreographyShot(pool, songKey, cycle, slot) {
  const total = Math.max(1, pool.length);
  const seed = hashText(`${songKey || 'untitled'}:edit:${cycle}`);
  const direction = seed & 1 ? 1 : -1;
  const rotation = (seed >>> 1) % total;
  return pool[(rotation + direction * slot + total * 2) % total];
}

function resolveScene(index, setting, songKey = '', text = '') {
  if (setting && setting !== 'auto' && SCENES.includes(setting)) return setting;
  // Keep an opening frame for orientation, then give every song a stable but
  // evolving edit sequence. Earlier versions looped the same five shots every
  // five lyric rows; a long verse therefore started to feel like a slideshow.
  // Each four-line chapter now rotates/reverses its non-poster shots from the
  // song identity, while remaining deterministic when revisiting a track.
  if (index === 0) return 'poster';
  if (/[\u0021\uFF01\u003F\uFF1F]/u.test(text) || (String(text).trim().length <= 3 && index % 3 === 0)) return 'impact';
  const choreography = AUTO_CHOREOGRAPHIES[hashText(songKey || 'untitled') % AUTO_CHOREOGRAPHIES.length];
  const pool = choreography.filter(scene => scene !== 'poster');
  const phase = Math.max(0, index - 1);
  const cycle = Math.floor(phase / Math.max(1, pool.length));
  const slot = phase % Math.max(1, pool.length);
  let scene = resolveChoreographyShot(pool, songKey, cycle, slot);
  if (phase > 0 && slot === 0) {
    const previous = resolveChoreographyShot(pool, songKey, cycle - 1, pool.length - 1);
    if (scene === previous) scene = pool[(pool.indexOf(scene) + 1) % pool.length];
  }
  return scene;
}

function resolveAccent(config, themeColor, preset, autoTemplate = false) {
  const palette = {
    preset: PV_PRESETS[preset]?.accent || '#7fd8ff',
    theme: themeColor || 'var(--primary)',
    coral: '#ff6b79',
    cyan: '#66e7ff',
    lime: '#d9ff5c',
    paper: '#ffffff'
  };
  const mode = config?.ktvAccent || 'auto';
  if (mode === 'custom') return config?.ktvCustomColor || palette.coral;
  if (mode === 'auto') return autoTemplate && hueFromColor(themeColor) !== null ? palette.theme : palette.preset;
  return palette[mode] || palette.preset;
}

function hashText(value = '') {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function hueFromColor(color) {
  const match = String(color || '').trim().match(/^#([\da-f]{6}|[\da-f]{3})$/i);
  if (!match) return null;
  const source = match[1].length === 3 ? match[1].split('').map(char => char + char).join('') : match[1];
  const rgb = [0, 2, 4].map(offset => Number.parseInt(source.slice(offset, offset + 2), 16) / 255);
  const max = Math.max(...rgb);
  const min = Math.min(...rgb);
  if (max - min < 0.08) return null;
  let hue = 0;
  if (max === rgb[0]) hue = ((rgb[1] - rgb[2]) / (max - min)) % 6;
  else if (max === rgb[1]) hue = (rgb[2] - rgb[0]) / (max - min) + 2;
  else hue = (rgb[0] - rgb[1]) / (max - min) + 4;
  return (hue * 60 + 360) % 360;
}

// Auto mode chooses once from the cover hue and a stable song identity. The
// same track therefore keeps a coherent template instead of cutting through
// unrelated visual styles on every lyric line.
function resolvePreset(config, songKey, themeColor, switchIndex = 0) {
  const requested = config?.ktvPreset || 'auto';
  const presetPool = Array.isArray(config?.ktvPresetPool)
    ? config.ktvPresetPool.filter(value => PV_PRESETS[value] && !DISABLED_PV_PRESETS.has(value))
    : [];
  if (requested === 'multi' && presetPool.length) {
    return presetPool[hashText(`${songKey || 'untitled'}:multi:${Math.max(0, Number(switchIndex) || 0)}`) % presetPool.length];
  }
  if (requested !== 'auto' && PV_PRESETS[requested] && !DISABLED_PV_PRESETS.has(requested)) return requested;
  const hue = hueFromColor(themeColor);
  const groups = hue === null
    ? ['staggered-text', 'calm-villain', 'custom']
    : hue < 24 || hue >= 340
      ? ['staggered-text', 'calm-villain', 'custom']
      : hue < 58
        ? ['fly-me-to-the-moon', 'geometric', 'paper-cut']
        : hue < 155
          ? ['matrix', 'kawaii-pixel', 'blue-structure']
          : hue < 245
            ? ['blue-structure', 'haruhikage', 'matrix']
            : hue < 305
              ? ['staggered-text', 'calm-villain', 'haruhikage']
              : ['girly-clouds', 'sweet-pink', 'kawaii-pixel'];
  return groups[hashText(`${songKey || 'untitled'}:${Math.round(hue ?? -1)}`) % groups.length];
}

function resolveTextEffect(config, preset) {
  const selected = config?.ktvTextEffect || 'auto';
  return selected === 'template'
    || selected === 'auto'
    || selected === 'template-rich'
    || selected === 'template-single'
    ? (PRESET_TEXT_EFFECTS[preset] || 'slice')
    : selected;
}

function resolveScript(text = '') {
  const value = String(text);
  if (/[\u3040-\u30ff]/u.test(value)) return 'jp';
  if (/[\u3400-\u9fff]/u.test(value)) return 'cjk';
  if (/[a-z]/i.test(value)) return 'latin';
  return 'mixed';
}

// A lyric line gets a visual cue in addition to its timed glyphs. This gives
// every cut an editorial focal point (hero letter / after-image) rather than
// making the foreground read like a conventional karaoke row.
function resolveKineticCues(tokens = []) {
  const visible = tokens.filter(token => String(token?.text || '').trim());
  if (!visible.length) return { hero: '\u8def', echo: '\u8def', heroLength: 1, echoLength: 1 };
  const punctuation = /[\u002C\u3001\uFF0C\u002E\u3002\u0021\uFF01\u003F\uFF1F\u2026]/u;
  const cueSegments = [];
  let current = [];
  visible.forEach((token, index) => {
    if (punctuation.test(String(token?.text || ''))) {
      if (current.length) cueSegments.push({ start: current[0].index, end: current[current.length - 1].index, tokens: current });
      current = [];
      return;
    }
    current.push({ ...token, index });
  });
  if (current.length) cueSegments.push({ start: current[0].index, end: current[current.length - 1].index, tokens: current });
  const middle = Math.floor((visible.length - 1) * 0.56);
  const matchedSegmentIndex = cueSegments.findIndex(segment => middle >= segment.start && middle <= segment.end);
  const segmentIndex = matchedSegmentIndex >= 0
    ? matchedSegmentIndex
    : cueSegments.reduce((closest, segment, index) => {
      const distance = Math.min(Math.abs(middle - segment.start), Math.abs(middle - segment.end));
      const closestSegment = cueSegments[closest];
      const closestDistance = Math.min(Math.abs(middle - closestSegment.start), Math.abs(middle - closestSegment.end));
      return distance < closestDistance ? index : closest;
    }, 0);
  const segment = cueSegments[segmentIndex] || { tokens: visible.map((token, index) => ({ ...token, index })) };
  const selected = segment.tokens;
  const isCjkSequence = selected.some(token => /[\u3040-\u30ff\u3400-\u9fff]/u.test(String(token.text)));
  const heroSpan = isCjkSequence ? (selected.length >= 9 ? 3 : selected.length >= 5 ? 2 : 1) : 1;
  const localMiddle = Math.floor((selected.length - 1) * 0.56);
  const heroStart = Math.max(0, Math.min(selected.length - heroSpan, localMiddle - Math.floor(heroSpan / 2)));
  const hero = selected.slice(heroStart, heroStart + heroSpan).map(token => token.text).join('') || selected[0]?.text || visible[0].text;
  const echoSpan = isCjkSequence && selected.length >= 8 ? 2 : 1;
  const echoStart = Math.min(selected.length - echoSpan, heroStart + heroSpan + Math.max(0, Math.floor(selected.length / 4)));
  const nextSegment = cueSegments[segmentIndex + 1]?.tokens || selected;
  const echo = (selected.slice(Math.max(0, echoStart), Math.max(0, echoStart) + echoSpan).map(token => token.text).join('') || nextSegment.slice(0, echoSpan).map(token => token.text).join('') || hero);
  return { hero, echo, heroLength: splitGraphemes(hero).length, echoLength: splitGraphemes(echo).length };
}

// A phrase needs a few editorial beats in addition to its word timings. These
// deterministic anchors turn a long string into a small sequence of visual
// hits without adding another animation loop or risking absolute-card overlap.
function resolvePhraseEmphasis(tokens = [], role = 'verse') {
  const count = tokens.length;
  if (!count) return new Set();
  const anchors = role === 'hook' ? [0, 0.28, 0.58, 0.86] : [0.22, 0.56, 0.84];
  const emphasis = new Set();
  anchors.forEach((ratio) => emphasis.add(Math.min(count - 1, Math.max(0, Math.round((count - 1) * ratio)))));
  tokens.forEach((token, index) => {
    if (/[!\u3002\u3001\u30fb\u2026\u2014?]/u.test(String(token?.text || ''))) emphasis.add(index);
  });
  return emphasis;
}

const MATRIX_PINYIN = Object.freeze({
  我: 'wo', 你: 'ni', 他: 'ta', 她: 'ta', 它: 'ta', 们: 'men', 的: 'de', 了: 'le', 是: 'shi', 在: 'zai', 有: 'you', 和: 'he', 不: 'bu', 一: 'yi', 个: 'ge', 人: 'ren', 这: 'zhe', 那: 'na', 来: 'lai', 去: 'qu', 看: 'kan', 听: 'ting', 说: 'shuo', 想: 'xiang', 爱: 'ai', 心: 'xin', 梦: 'meng', 夜: 'ye', 光: 'guang', 天: 'tian', 地: 'di', 世界: 'shi jie', 欢迎: 'huan ying', 回来: 'hui lai', 永远: 'yong yuan', 未来: 'wei lai', 现在: 'xian zai', 再见: 'zai jian',
  大: 'da', 小: 'xiao', 生: 'sheng', 活: 'huo', 时间: 'shi jian', 记忆: 'ji yi', 声音: 'sheng yin', 歌: 'ge', 路: 'lu', 风: 'feng', 雨: 'yu', 月: 'yue', 星: 'xing', 黑: 'hei', 白: 'bai', 绿: 'lv', 蓝: 'lan', 红: 'hong', 新: 'xin', 旧: 'jiu', 真: 'zhen', 假: 'jia', 自由: 'zi you', 希望: 'xi wang',
  あ: 'a', い: 'i', う: 'u', え: 'e', お: 'o', か: 'ka', き: 'ki', く: 'ku', け: 'ke', こ: 'ko', さ: 'sa', し: 'shi', す: 'su', せ: 'se', そ: 'so', た: 'ta', ち: 'chi', つ: 'tsu', て: 'te', と: 'to', な: 'na', に: 'ni', ぬ: 'nu', ね: 'ne', の: 'no', は: 'ha', ひ: 'hi', ふ: 'fu', へ: 'he', ほ: 'ho', ま: 'ma', み: 'mi', む: 'mu', め: 'me', も: 'mo', や: 'ya', ゆ: 'yu', よ: 'yo', ら: 'ra', り: 'ri', る: 'ru', れ: 're', ろ: 'ro', わ: 'wa', を: 'o', ん: 'n',
  ア: 'a', イ: 'i', ウ: 'u', エ: 'e', オ: 'o', カ: 'ka', キ: 'ki', ク: 'ku', ケ: 'ke', コ: 'ko', サ: 'sa', シ: 'shi', ス: 'su', セ: 'se', ソ: 'so', タ: 'ta', チ: 'chi', ツ: 'tsu', テ: 'te', ト: 'to', ナ: 'na', ニ: 'ni', ヌ: 'nu', ネ: 'ne', ノ: 'no', ハ: 'ha', ヒ: 'hi', フ: 'fu', ヘ: 'he', ホ: 'ho', マ: 'ma', ミ: 'mi', ム: 'mu', メ: 'me', モ: 'mo', ヤ: 'ya', ユ: 'yu', ヨ: 'yo', ラ: 'ra', リ: 'ri', ル: 'ru', レ: 're', ロ: 'ro', ワ: 'wa', ヲ: 'o', ン: 'n'
});

function resolveMatrixReading(text = '') {
  const value = String(text || '').trim();
  if (!value || value.length > 10) return '';
  if (/^[\x20-\x7e]+$/.test(value)) return value.toLowerCase().slice(0, 14);
  if (MATRIX_PINYIN[value]) return MATRIX_PINYIN[value];
  const units = splitGraphemes(value).map(unit => MATRIX_PINYIN[unit] || (/^[\u3040-\u30ff]$/u.test(unit) ? unit : '')).filter(Boolean);
  return units.length ? units.join(' ') : '';
}

function resolveMatrixByte(text = '') {
  const value = String(text || '').trim();
  if (!value) return '00000000';
  // A tiny deterministic byte trace is more legible than long random-looking
  // strings, while staying tied to the actual current lyric token.
  const checksum = splitGraphemes(value).reduce((total, unit) => (total + unit.codePointAt(0)) & 0xff, 0);
  return checksum.toString(2).padStart(8, '0');
}

function MatrixDiagnosticRail({ tokens = [], index = 0 }) {
  const packets = tokens.slice(0, 8);
  if (!packets.length) return null;
  return (
    <div className="kpv-matrix-diagnostic-rail" aria-hidden="true">
      <b>PKT {String(index + 1).padStart(2, '0')} / 0101</b>
      <div className="kpv-matrix-diagnostic-packets">
        {packets.map((token, packetIndex) => {
          const reading = resolveMatrixReading(token.text) || 'raw';
          return <span className="kpv-matrix-diagnostic-packet" key={`${token.key || token.text}-${packetIndex}`}><em>{resolveMatrixByte(token.text)}</em><small>{reading}</small></span>;
        })}
      </div>
      <strong>TRACE / LOCKED</strong>
    </div>
  );
}

function resolveCityArrivalCode(text = '') {
  const total = splitGraphemes(String(text || '')).reduce((sum, unit) => sum + (unit.codePointAt(0) || 0), 0);
  return String(total % 100).padStart(2, '0');
}

function CityArrivalBoard({ tokens = [], index = 0 }) {
  const cells = tokens.slice(0, 8);
  if (!cells.length) return null;
  return (
    <div className="kpv-city-arrival-board" aria-hidden="true">
      <b>PLATFORM 07 / {String(index + 1).padStart(2, '0')}</b>
      <div className="kpv-city-arrival-cells">
        {cells.map((token, cellIndex) => <span className="kpv-city-arrival-cell" key={`${token.key || token.text}-${cellIndex}`}><em>{token.text}</em><small>CAR {resolveCityArrivalCode(token.text)}</small></span>)}
      </div>
      <strong>WESTBOUND / LIVE</strong>
    </div>
  );
}

function BlueMeasureStrip({ tokens = [] }) {
  const cells = tokens.slice(0, 8);
  if (!cells.length) return null;
  return (
    <div className="kpv-blue-measure-strip" aria-hidden="true">
      {cells.map((token, cellIndex) => <span className="kpv-blue-measure-cell" key={`${token.key || token.text}-${cellIndex}`}><em>{String(cellIndex + 1).padStart(2, '0')} / {token.text}</em></span>)}
    </div>
  );
}

function CinemaContactSheet({ tokens = [], index = 0 }) {
  const cells = tokens.slice(0, 7);
  if (!cells.length) return null;
  return (
    <div className="kpv-cinema-contact-sheet" aria-hidden="true">
      {cells.map((token, cellIndex) => <span className="kpv-cinema-contact-cell" key={`${token.key || token.text}-${cellIndex}`}><em>{token.text}</em><small>{String(index + 1).padStart(2, '0')}.{String(cellIndex + 1).padStart(2, '0')}</small></span>)}
    </div>
  );
}

// The moon scene uses the line itself as an observation log.  This makes the
// orbit language feel authored per lyric, while keeping the ambient scene free
// of another render-loop or timer.
function resolveLunarPhase(text = '') {
  const checksum = splitGraphemes(String(text || '')).reduce((total, unit) => total + (unit.codePointAt(0) || 0), 0);
  return ['NEW', 'WAX', 'QTR', 'GIB', 'FULL', 'WAN', 'LAST', 'CRES'][checksum % 8];
}

function LunarObservationRail({ tokens = [], index = 0 }) {
  const cells = tokens.slice(0, 8);
  if (!cells.length) return null;
  return (
    <div className="kpv-luna-observation-rail" aria-hidden="true">
      <b>ORBIT 07 / {String(index + 1).padStart(2, '0')}</b>
      <div className="kpv-luna-observation-cells">
        {cells.map((token, cellIndex) => <span className="kpv-luna-observation-cell" key={`${token.key || token.text}-${cellIndex}`}><em>{resolveLunarPhase(token.text)}</em><small>{String(cellIndex + 1).padStart(2, '0')} / {token.text}</small></span>)}
      </div>
      <strong>AZ 072 / LOCK</strong>
    </div>
  );
}

// A light morning forecast doubles as a lyric ledger: each cloud stamp comes
// from the active phrase, so the scene feels like stationery in motion rather
// than a generic pastel backdrop.
function resolveCloudStamp(text = '') {
  const checksum = splitGraphemes(String(text || '')).reduce((total, unit) => total + (unit.codePointAt(0) || 0), 0);
  return ['SUN', 'MIST', 'BREEZE', 'PETAL', 'BLUE', 'DAWN'][checksum % 6];
}

function CloudMorningRibbon({ tokens = [], index = 0 }) {
  const stamps = tokens.slice(0, 7);
  if (!stamps.length) return null;
  return (
    <div className="kpv-cloud-morning-ribbon" aria-hidden="true">
      <b>POSTMARK / {String(index + 1).padStart(2, '0')}</b>
      <div className="kpv-cloud-morning-stamps">
        {stamps.map((token, stampIndex) => <span className="kpv-cloud-morning-stamp" key={`${token.key || token.text}-${stampIndex}`}><em>{resolveCloudStamp(token.text)}</em><small>{String(stampIndex + 1).padStart(2, '0')} · {token.text}</small></span>)}
      </div>
      <strong>SOFT MAIL</strong>
    </div>
  );
}

// The arcade panel is a deterministic combo ledger, not a ticking score. Its
// cells are produced from the active lyric units so the game language stays
// connected to the song without adding a timing loop.
function resolvePixelCombo(text = '', index = 0) {
  const checksum = splitGraphemes(String(text || '')).reduce((total, unit) => total + (unit.codePointAt(0) || 0), 0);
  return `${String(index + 1).padStart(2, '0')}-${(checksum % 100).toString().padStart(2, '0')}`;
}

function PixelComboLedger({ tokens = [], index = 0 }) {
  const cells = tokens.slice(0, 8);
  if (!cells.length) return null;
  return (
    <div className="kpv-pixel-combo-ledger" aria-hidden="true">
      <b>COMBO / {String(index + 1).padStart(2, '0')}</b>
      <div className="kpv-pixel-combo-cells">
        {cells.map((token, cellIndex) => <span className="kpv-pixel-combo-cell" key={`${token.key || token.text}-${cellIndex}`}><em>{resolvePixelCombo(token.text, cellIndex)}</em><small>{token.text}</small></span>)}
      </div>
      <strong>READY × 8</strong>
    </div>
  );
}

// The garden record is assembled from the lyric itself. It creates the quiet
// feeling of a handwritten flower tag without an ambient particle simulation
// or a second timing source.
function resolveHaruPetalMark(text = '') {
  const checksum = splitGraphemes(String(text || '')).reduce((total, unit) => total + (unit.codePointAt(0) || 0), 0);
  return ['BUD', 'BLOOM', 'SHADE', 'BREEZE', 'PETAL', 'DAWN'][checksum % 6];
}

function HaruPetalLedger({ tokens = [], index = 0 }) {
  const petals = tokens.slice(0, 7);
  if (!petals.length) return null;
  return (
    <div className="kpv-haru-petal-ledger" aria-hidden="true">
      <b>GARDEN / {String(index + 1).padStart(2, '0')}</b>
      <div className="kpv-haru-petal-notes">
        {petals.map((token, petalIndex) => <span className="kpv-haru-petal-note" key={`${token.key || token.text}-${petalIndex}`}><em>{resolveHaruPetalMark(token.text)}</em><small>{String(petalIndex + 1).padStart(2, '0')} · {token.text}</small></span>)}
      </div>
      <strong>DAWN TRACE</strong>
    </div>
  );
}

function resolvePlotPoint(token, pointIndex, total) {
  const value = String(token?.text || '');
  const checksum = splitGraphemes(value).reduce((sum, unit) => sum + (unit.codePointAt(0) || 0), 0);
  const safeTotal = Math.max(1, total - 1);
  return {
    x: 7 + (pointIndex / safeTotal) * 86,
    y: 64 - (checksum % 42),
    label: `${String(pointIndex + 1).padStart(2, '0')}:${(checksum % 100).toString().padStart(2, '0')}`
  };
}

function PlotTrajectory({ tokens = [] }) {
  const points = tokens.slice(0, 8).map((token, pointIndex, list) => ({ token, ...resolvePlotPoint(token, pointIndex, list.length) }));
  if (!points.length) return null;
  const polyline = points.map(({ x, y }) => `${x},${y}`).join(' ');
  return (
    <div className="kpv-plot-trajectory" aria-hidden="true">
      <svg viewBox="0 0 100 72" preserveAspectRatio="none">
        <polyline points={polyline} />
        {points.map(({ token, x, y, label }, pointIndex) => <g key={`${token.key || token.text}-${pointIndex}`}><circle cx={x} cy={y} r="1.4" /><text x={x} y={Math.max(9, y - 6)} textAnchor="middle">{label}</text></g>)}
      </svg>
    </div>
  );
}

function renderActivePvScene(preset) {
  switch (preset) {
    case 'girly-clouds': return <div className="kpv-art-scene kpv-art-scene--clouds" aria-hidden="true"><div className="kpv-cloud-bank"><i /><i /><i /><i /></div></div>;
    case 'kawaii-pixel': return <div className="kpv-art-scene kpv-art-scene--pixel" aria-hidden="true"><div className="kpv-pixel-ui"><i /><i /><i /><i /></div></div>;
    case 'haruhikage': return <div className="kpv-art-scene kpv-art-scene--haru" aria-hidden="true"><div className="kpv-haru-branch"><i /><i /><i /><i /><i /><i /></div></div>;
    case 'hysteric-night': return <div className="kpv-art-scene kpv-art-scene--hysteric" aria-hidden="true"><div className="kpv-hysteric-shards"><i /><i /><i /><i /></div></div>;
    case 'blue-impact': return <div className="kpv-art-scene kpv-art-scene--impact" aria-hidden="true"><div className="kpv-impact-burst"><i /><i /><i /><i /></div></div>;
    case 'kinetic-split': return <div className="kpv-art-scene kpv-art-scene--split" aria-hidden="true"><div className="kpv-split-planes"><i /><i /><i /></div></div>;
    case 'emotion-cinema': return <div className="kpv-art-scene kpv-art-scene--cinema" aria-hidden="true"><div className="kpv-cinema-gate"><i /><i /><i /></div></div>;
    case 'spider-web': return <div className="kpv-art-scene kpv-art-scene--web" aria-hidden="true"><div className="kpv-web-loom"><i /><i /><i /><i /><i /></div></div>;
    case 'paper-cut': return <div className="kpv-art-scene kpv-art-scene--paper" aria-hidden="true"><div className="kpv-paper-stack"><i /><i /><i /></div></div>;
    case 'sweet-pink': return <div className="kpv-art-scene kpv-art-scene--sweet" aria-hidden="true"><div className="kpv-scallop-stage"><i /><i /><i /></div></div>;
    case 'fly-me-to-the-moon': return <div className="kpv-art-scene kpv-art-scene--moon" aria-hidden="true"><div className="kpv-moon-stage"><i /><i /><i /></div></div>;
    case 'matrix': return <div className="kpv-art-scene kpv-art-scene--matrix" aria-hidden="true"><div className="kpv-matrix-stage"><i /><i /><i /><i /></div></div>;
    case 'night-city': return <div className="kpv-art-scene kpv-art-scene--city" aria-hidden="true"><div className="kpv-city-stage"><i /><i /><i /></div></div>;
    case 'cyber-grunge': return <div className="kpv-art-scene kpv-art-scene--cyber" aria-hidden="true"><div className="kpv-cyber-stage"><i /><i /><i /><i /></div></div>;
    case 'geometric': return <div className="kpv-art-scene kpv-art-scene--geo" aria-hidden="true"><div className="kpv-geo-stage"><i /><i /><i /></div></div>;
    case 'p5': return <div className="kpv-art-scene kpv-art-scene--p5" aria-hidden="true"><div className="kpv-p5-stage"><i /><i /><i /></div></div>;
    case 'staggered-text': return <div className="kpv-art-scene kpv-art-scene--stagger" aria-hidden="true"><div className="kpv-stagger-stage"><i /><i /><i /><i /></div></div>;
    case 'calm-villain': return <div className="kpv-art-scene kpv-art-scene--villain" aria-hidden="true"><div className="kpv-villain-stage"><i /><i /><i /></div></div>;
    case 'crime-scene': return <div className="kpv-art-scene kpv-art-scene--crime" aria-hidden="true"><div className="kpv-crime-stage"><i /><i /><i /></div></div>;
    case 'custom': return <div className="kpv-art-scene kpv-art-scene--custom" aria-hidden="true"><div className="kpv-custom-stage"><i /><i /><i /></div></div>;
    default: return null;
  }
}

function FlyMoonSpatialCloud({ songKey = '', activeIndex = 0, coverUrl = '', renderQuality = 'balanced' }) {
  const points = useMemo(() => Array.from({ length: renderQuality === 'efficient' ? 18 : 32 }, (_, pointIndex) => {
    const seed = hashText(['moon-cloud', songKey || 'track', pointIndex].join('|'));
    const angle = ((seed % 360) * Math.PI) / 180;
    const radius = 16 + (Math.floor(seed / 360) % 31);
    return {
      x: 50 + Math.cos(angle) * radius,
      y: 48 + Math.sin(angle) * radius * .62,
      z: -420 + (seed % 760),
      size: 2 + (seed % 5),
      delay: -(seed % 9000) / 1000,
      alpha: .25 + (seed % 45) / 100
    };
  }), [renderQuality, songKey]);
  const links = useMemo(() => points.slice(0, Math.min(18, points.length - 1)).map((point, linkIndex) => {
    const target = points[(linkIndex * 5 + 7) % points.length];
    const dx = target.x - point.x;
    const dy = target.y - point.y;
    return {
      x: point.x,
      y: point.y,
      width: Math.max(5, Math.hypot(dx, dy)),
      rotation: Math.atan2(dy, dx) * 180 / Math.PI,
      delay: -(linkIndex % 7) * .7
    };
  }), [points]);
  const safeCover = String(coverUrl || '').replace(/"/g, '%22');
  return (
    <div className="kpv-fly-cloud" data-quality={renderQuality} aria-hidden="true">
      {safeCover && <div className="kpv-fly-cloud-cover kpv-fly-cloud-cover--far" style={{ backgroundImage: 'url("' + safeCover + '")' }} />}
      {safeCover && <div className="kpv-fly-cloud-cover kpv-fly-cloud-cover--near" style={{ backgroundImage: 'url("' + safeCover + '")' }} />}
      <div className="kpv-fly-cloud-grid"><i /><i /><i /></div>
      <div className="kpv-fly-cloud-plane">
        <div className="kpv-fly-cloud-links">{links.map((link, index) => <b key={index} style={{ left: link.x + '%', top: link.y + '%', width: link.width + '%', '--kpv-cloud-rotation': link.rotation + 'deg', '--kpv-cloud-delay': link.delay + 's' }} />)}</div>
        <div className="kpv-fly-cloud-points">{points.map((point, index) => <i key={index} style={{ left: point.x + '%', top: point.y + '%', width: point.size + 'px', height: point.size + 'px', opacity: point.alpha, '--kpv-cloud-z': point.z + 'px', '--kpv-cloud-delay': point.delay + 's' }} />)}</div>
      </div>
      <div className="kpv-fly-cloud-orbit"><i /><i /><b /></div>
      <div className="kpv-fly-cloud-readout"><b>LUNAR CLOUD / NODE {String(activeIndex + 1).padStart(2, '0')}</b><span>AZ 072 / EL 25 / LYRIC CAMERA LOCK</span></div>
    </div>
  );
}

function KtvReactiveBackdrop({ model, coverUrl = '', mode = 'rich', renderQuality = 'balanced' }) {
  if (!model || mode === 'minimal') return null;
  const preset = model.preset || 'custom';
  const lyricText = String(model.line?.text || '').trim();
  const backgroundText = lyricText || 'ICHIGOMUSIC';
  const showCover = Boolean(coverUrl) && mode !== 'lyrics';
  const showLyrics = mode !== 'cover';
  const fragments = splitGraphemes(backgroundText).filter(Boolean).slice(0, 18);
  const trail = fragments.length ? fragments.join(' ') : backgroundText;
  const textureStyle = { backgroundImage: 'url("' + String(coverUrl).replace(/"/g, '%22') + '")' };
  return (
    <div
      className={'kpv-reactive-backdrop kpv-reactive-backdrop--' + preset + ' kpv-reactive-backdrop--' + mode}
      data-role={model.role}
      data-quality={renderQuality}
      aria-hidden="true"
    >
      {showCover && <div className="kpv-backdrop-cover-field" style={textureStyle}><i /><i /><i /></div>}
      {showLyrics && <div className="kpv-backdrop-lyric-field">
        {[0, 1, 2, 3].map((row) => <b key={row} style={{ '--kpv-backdrop-row': row, '--kpv-backdrop-offset': String(row * -8) + '%', '--kpv-backdrop-duration': String(15 + row) + 's', '--kpv-backdrop-delay': String(row * -3) + 's', '--kpv-backdrop-right': String(8 + row * 19) + '%' }}>{row % 2 ? trail : backgroundText}</b>)}
        <span>{backgroundText}</span>
      </div>}
      <div className="kpv-backdrop-trace" aria-hidden="true"><i /><i /><i /><i /><i /></div>
    </div>
  );
}

function KtvThemeLayer({ model }) {
  if (!model?.theme || model.preset === 'geometric' || model.preset === 'fly-me-to-the-moon') return null;
  const { theme, scene, index, role, preset } = model;
  const cue = resolveKineticCues(model.tokens || []);
  const contextText = theme.context || (theme.secondary && theme.tertiary ? `${theme.primary} 路 ${theme.secondary} 路 ${theme.tertiary}` : '');
  const themeUnits = (theme.units || []).filter(Boolean).slice(0, 6);
  return (
    <div
      className={`kpv-theme-layer kpv-line--active kpv-preset--${preset} kpv-scene--${scene} kpv-theme-script--${theme.script}`}
      data-role={role}
      aria-hidden="true"
    >
      <div className="kpv-ghost">{theme.ghost || theme.primary}</div>
      {contextText && <div className="kpv-context-line">{contextText}</div>}
      <div className="kpv-echoes">
        {(themeUnits.length ? themeUnits : [theme.secondary, theme.tertiary]).filter(Boolean).map((unit, unitIndex, units) => (
          <b key={`${unit}-${unitIndex}`} style={getThemeUnitPlacement(preset, scene, unitIndex, units.length)}>{unit}</b>
        ))}
      </div>
      <div className={`kpv-keyframe kpv-keyframe--${theme.script}${cue.heroLength >= 3 ? ' kpv-keyframe--phrase' : cue.heroLength === 2 ? ' kpv-keyframe--pair' : ''}`}>
        <span>KEYFRAME / {String(index + 1).padStart(2, '0')}</span>
        <b>{theme.hero}</b>
        {theme.secondary && <i>{theme.secondary}</i>}
      </div>
    </div>
  );
}

function KtvLine({ model, fontPx, fontStack, showLyricIndex = true, presetLabel, renderQuality, register, config = {} }) {
  const { line, tokens, index, relation, scene, effect, layout, rhythm, act, role, sectionStart, revealMode, preset, motionVariant, distance = 0 } = model;
  const isActive = relation === 'active';
  const wordRenderer = PRESET_WORD_RENDERERS[preset] || PRESET_WORD_RENDERERS.custom;
  const wordVariant = model.wordVariant || (PRESET_WORD_VARIANTS[preset] || PRESET_WORD_VARIANTS.custom)[0];
  // Keep the callback ref stable while a line remains in the same relation.
  // Recreating it on every clock-driven parent render used to unregister and
  // re-register every visible line, resetting token state and restarting the
  // active-line animation even when the lyric time had barely moved.
  const displayTokens = condenseCompositionTokens(tokens, layout, renderQuality);
  const tokenSignature = displayTokens.map(token => `${token.key ?? ''}:${token.text}:${token.start}:${token.end}:${token.revealGroup ?? 0}:${token.revealStart ?? ''}:${token.revealEnd ?? ''}`).join('|');
  const lineRef = useCallback((node) => register(model.key, node, relation), [model.key, relation, register, tokenSignature]);
  const label = sectionStart ? 'NEW CHAPTER' : role === 'hook' ? 'CHORUS / HOOK' : relation === 'active' ? 'NOW SINGING' : relation === 'previous' ? 'MEMORY' : 'NEXT LINE';
  const script = resolveScript(line.text);
  const phraseEmphasis = resolvePhraseEmphasis(displayTokens, role);
  const isFlyPreset = preset === 'fly-me-to-the-moon';
  const flySpatialPoint = isFlyPreset ? resolveFlySpatialPoint(distance, index, line.text) : null;
  const isPixelPreset = preset === 'kawaii-pixel';
  return (
    <article
      ref={lineRef}
      className={`kpv-line kpv-line--${relation} kpv-scene--${scene} kpv-effect--${effect} kpv-layout--${layout} kpv-script--${script} kpv-reveal--${revealMode} kpv-motion--${motionVariant} kpv-word-renderer--${wordRenderer}`}
      data-line-key={model.key}
      data-rhythm={rhythm}
      data-motion={motionVariant}
      data-act={act}
      data-role={role}
      data-section={sectionStart ? 'start' : 'continue'}
      data-word-renderer={wordRenderer}
      data-word-variant={wordVariant}
      data-spatial-distance={distance}
      style={flySpatialPoint ? {
        '--kpv-fly-x': `${flySpatialPoint.x}vw`,
        '--kpv-fly-y': `${flySpatialPoint.y}vh`,
        '--kpv-fly-z': `${flySpatialPoint.z}px`,
        '--kpv-fly-r': `${flySpatialPoint.rotation}deg`,
        '--kpv-fly-scale': String(flySpatialPoint.scale)
      } : undefined}
      aria-hidden={relation !== 'active'}
    >
       {isActive && <>
         <div className="kpv-geometry" aria-hidden="true"><i /><i /><i /></div>
         <div className="kpv-burst" aria-hidden="true"><i /><i /><i /><i /></div>
         <div className="kpv-systems" aria-hidden="true"><i>VECTOR / {String(index + 1).padStart(2, '0')}</i><i>LYRIC SIGNAL</i><i>闂?01 10 01</i></div>
       </>}
      <div className="kpv-copy">
        {isActive && <div className="kpv-lyric-signal" aria-hidden="true"><i /><b /></div>}
        {isActive && <div className="kpv-progress-trace" aria-hidden="true"><i /><b /></div>}
        {isActive && preset === 'matrix' && <div className="kpv-matrix-word-frame" aria-hidden="true"><i /><i /><i /><i /><b>INPUT / {String(index + 1).padStart(2, '0')}</b></div>}
        {isActive && preset === 'matrix' && <><div className="kpv-matrix-prompt" aria-hidden="true"><i>&gt;_</i><b>DECRYPTING LYRIC STREAM / {String(index + 1).padStart(2, '0')}</b></div><MatrixDiagnosticRail tokens={displayTokens} index={index} /></>}
        {isActive && preset === 'night-city' && <CityArrivalBoard tokens={displayTokens} index={index} />}
        {isActive && preset === 'blue-structure' && <BlueMeasureStrip tokens={displayTokens} />}
        {isActive && preset === 'emotion-cinema' && <CinemaContactSheet tokens={displayTokens} index={index} />}
        {isActive && preset === 'fly-me-to-the-moon' && <LunarObservationRail tokens={displayTokens} index={index} />}
        {isActive && preset === 'girly-clouds' && <CloudMorningRibbon tokens={displayTokens} index={index} />}
        {isActive && preset === 'kawaii-pixel' && <PixelComboLedger tokens={displayTokens} index={index} />}
        {isActive && preset === 'haruhikage' && <HaruPetalLedger tokens={displayTokens} index={index} />}
        {isActive && preset === 'p5' && <PlotTrajectory tokens={displayTokens} />}
        <div className="kpv-phrase-ribbon" aria-hidden="true"><i /><b>PHRASE / {String(index + 1).padStart(2, '0')} 闂?{role.toUpperCase()}</b></div>
        <div className="kpv-caption">{showLyricIndex && <span>{String(index + 1).padStart(2, '0')}</span>}<b>{label}</b><em>{act.toUpperCase()} / {presetLabel}</em></div>
        <div className="kpv-words" style={{ fontSize: `${fontPx}px`, fontFamily: fontStack, '--kpv-token-count': displayTokens.length, '--kpv-reveal-duration': `${Math.min(1.35, Math.max(0.42, (Number(line?.duration) || 4.2) * 0.38))}s` }}>
           {displayTokens.reduce((renderedTokens, token, tokenIndex) => {
             const [slotX, slotY, slotRotation, slotScale] = getAdaptiveSlot(tokenIndex, displayTokens.length, layout);
             const tokenKind = token.kind || 'grapheme';
             const previousTokenVariant = renderedTokens.previousVariant;
             const tokenVariant = resolveTokenWordVariant(config, preset, wordVariant, token, tokenIndex, displayTokens.length, index, role, previousTokenVariant);
             const tokenSeed = hashText([preset, tokenVariant, index, tokenIndex, token.text].join('|'));
             const blockScale = layout !== 'jp-phrase' && /[\u3040-\u30ff\u3400-\u9fff]/u.test(token.text)
               ? Math.min(1, 1.5 / Math.max(1, splitGraphemes(token.text).length))
               : 1;
             renderedTokens.items.push(<span
               className={`kpv-token kpv-token--${tokenKind}`}
              key={token.key}
              data-start={token.start}
              data-end={token.end}
              data-reveal-group={token.revealGroup ?? 0}
              data-reveal-start={token.revealStart ?? token.start}
              data-reveal-end={token.revealEnd ?? token.end}
              data-matrix-code={preset === 'matrix' ? resolveMatrixByte(token.text) : undefined}
              data-state={relation === 'previous' ? 'done' : 'waiting'}
               data-emphasis={phraseEmphasis.has(tokenIndex) ? 'true' : 'false'}
               data-token-variant={tokenVariant}
               data-token-kind={tokenKind}
               style={{
                whiteSpace: token.text === ' ' ? 'pre' : undefined,
                '--kpv-index': tokenIndex,
                '--kpv-stagger': `${(tokenIndex % 2 === 0 ? -1 : 1) * (7 + (tokenIndex % 3) * 4)}px`,
                '--kpv-scatter-x': `${((tokenIndex * 37) % 5 - 2) * 28}px`,
                '--kpv-scatter-y': `${((tokenIndex * 19) % 5 - 2) * 20}px`,
                '--kpv-scatter-r': `${((tokenIndex * 29) % 7 - 3) * 7}deg`,
                '--kpv-slot-x': `${slotX}%`,
                '--kpv-slot-y': `${slotY}%`,
                '--kpv-slot-r': `${slotRotation}deg`,
                 '--kpv-theme-token-scale': getPresetTokenScale(preset, tokenIndex, token, displayTokens.length),
                 '--kpv-slot-scale': slotScale * blockScale * getTokenVisualScale(token, tokenIndex, layout),
                 '--kpv-variant-delay': `${(tokenSeed % 7) * 0.012}s`,
                 '--kpv-variant-scale': `${0.96 + (tokenSeed % 9) * 0.01}`,
                fontSize: isPixelPreset
                  ? '1em'
                  : ['blue-cards', 'grunge-cards', 'impact-scatter', 'vertical-columns', 'orbit-board'].includes(layout)
                  ? undefined
                  : `calc(${getTokenVisualScale(token, tokenIndex, layout)}em * var(--kpv-theme-token-scale,1))`,
                '--kpv-count': displayTokens.length
              }}
            >
              <span
                className="kpv-token-motion"
                data-matrix-code={preset === 'matrix' ? resolveMatrixByte(token.text) : undefined}
              >
                <span className="kpv-token-base">{token.text}</span>
                <span className="kpv-token-fill" aria-hidden="true">{token.text}</span>
                {preset === 'matrix' && resolveMatrixReading(token.text) && <small className="kpv-matrix-reading" aria-hidden="true">{resolveMatrixReading(token.text)}</small>}
              </span>
               </span>
             );
             renderedTokens.previousVariant = tokenVariant;
             return renderedTokens;
           }, { items: [], previousVariant: '' }).items}
        </div>
        <div className="kpv-meter" aria-hidden="true"><i /></div>
      </div>
    </article>
  );
}

/**
 * KTV Text PV: a compact kinetic-typography stage. It intentionally updates
 * CSS custom properties from the shared lyric clock instead of storing every
 * 16ms progress sample in React state; rendering stays smooth on long lyrics.
 */
export default function KineticKtvLyrics({
  lyrics = [],
  activeLineIndex = -1,
  engineRef,
  fontPx = 36,
  translationPx = 18,
  fontStack,
  themeColor,
  config = {},
  songKey,
  songTitle = '',
  songArtist = '',
  isPlaying = true,
  coverUrl = ''
}) {
  const lineNodes = useRef(new Map());
  const stageRef = useRef(null);
  const stageProgressRef = useRef(-1);
  const audioPulseRef = useRef({ buffer: null, value: 0, lastSampleAt: 0, lastPainted: -1 });
  const autoPresetRef = useRef({ songKey: null, preset: null, themeColor: null });
  const visualSongRef = useRef(songKey);
  const visualLyricsRef = useRef(null);
  const previewOriginRef = useRef(0);
  const coverLifecycleRef = useRef({ songKey, coverUrl, ready: true });
  const coverRevealFrameRef = useRef(0);
  const runtimeQualitySongRef = useRef(songKey);
  const [, refreshCoverLifecycle] = useState(0);
  const [previewIndex, setPreviewIndex] = useState(0);
  const [clockActiveIndex, setClockActiveIndex] = useState(-1);
  const [runtimeQuality, setRuntimeQuality] = useState(null);
  const previewEnabled = config.ktvPreviewEnabled === true;
  const stageLyrics = previewEnabled ? PV_PREVIEW_LYRICS : lyrics;
  const coverTextureReady = coverLifecycleRef.current.songKey === songKey
    && coverLifecycleRef.current.ready === true;
  const pvCoverUrl = coverTextureReady ? coverUrl : '';
  const songChangedForVisual = visualSongRef.current !== songKey;
  const lyricsChangedForVisual = visualLyricsRef.current !== null && visualLyricsRef.current !== stageLyrics;
  const visualTrackChanged = songChangedForVisual || lyricsChangedForVisual;
  const currentPlaybackTime = engineRef?.current?.getCurrentTime?.() || 0;
  useEffect(() => {
    const applyVisibilityBudget = () => {
      const stage = stageRef.current;
      if (!stage) return;
      if (document.hidden) stage.setAttribute('data-document-hidden', 'true');
      else stage.removeAttribute('data-document-hidden');
    };
    applyVisibilityBudget();
    document.addEventListener('visibilitychange', applyVisibilityBudget);
    return () => {
      document.removeEventListener('visibilitychange', applyVisibilityBudget);
      stageRef.current?.removeAttribute('data-document-hidden');
    };
  }, []);
  useEffect(() => {
    const cancelReveal = () => {
      if (coverRevealFrameRef.current) {
        window.cancelAnimationFrame(coverRevealFrameRef.current);
        coverRevealFrameRef.current = 0;
      }
    };
    cancelReveal();
    const lifecycle = coverLifecycleRef.current;
    if (lifecycle.songKey !== songKey) {
      // On a track boundary, do not let the previous track's cover remain in
      // the PV compositor while the new cover URL is still resolving. A URL
      // that is already different is safe to accept immediately; an equal
      // URL may simply be the stale value from the previous song.
      const sameCoverAsPreviousTrack = Boolean(coverUrl) && coverUrl === lifecycle.coverUrl;
      coverLifecycleRef.current = {
        songKey,
        coverUrl,
        ready: !sameCoverAsPreviousTrack
      };
      refreshCoverLifecycle(version => version + 1);
      if (sameCoverAsPreviousTrack) {
        // Give React one paint to commit the new track identity before
        // reusing an identical album-art URL. This removes the old-cover
        // flash without leaving shared album art hidden for the whole song.
        coverRevealFrameRef.current = window.requestAnimationFrame(() => {
          coverRevealFrameRef.current = 0;
          const current = coverLifecycleRef.current;
          if (current.songKey === songKey && current.coverUrl === coverUrl) {
            coverLifecycleRef.current = { ...current, ready: true };
            refreshCoverLifecycle(version => version + 1);
          }
        });
      }
      return cancelReveal;
    }
    if (lifecycle.coverUrl !== coverUrl) {
      coverLifecycleRef.current = { songKey, coverUrl, ready: true };
      refreshCoverLifecycle(version => version + 1);
    }
    return cancelReveal;
  }, [coverUrl, songKey]);
  const immediateVisualIndex = resolveVisualActiveIndex(
    stageLyrics,
    currentPlaybackTime + (Number(config.globalOffset) || 0),
    visualTrackChanged ? -1 : activeLineIndex
  );
  useEffect(() => {
    // Do this before the first post-song clock tick so the previous track's
    // active index cannot briefly select a random line from the new track.
    visualSongRef.current = songKey;
    visualLyricsRef.current = stageLyrics;
    if (previewEnabled || !stageLyrics.length) {
      setClockActiveIndex(-1);
      return undefined;
    }
    let boundaryTimerId = null;
    const syncVisualIndex = () => {
      const time = (engineRef?.current?.getCurrentTime?.() || 0) + (Number(config.globalOffset) || 0);
      const nextIndex = resolveVisualActiveIndex(stageLyrics, time, activeLineIndex);
      setClockActiveIndex(current => current === nextIndex ? current : nextIndex);
      if (!isPlaying) return;
      const boundaryIndex = findNextVisualBoundaryIndex(stageLyrics, time);
      if (boundaryIndex < 0) return;
      const boundaryTime = Number(stageLyrics[boundaryIndex]?.time || 0);
      const delay = Math.max(50, Math.min(2000, (boundaryTime - time) * 1000 + 8));
      boundaryTimerId = window.setTimeout(() => {
        boundaryTimerId = null;
        syncVisualIndex();
      }, delay);
    };
    syncVisualIndex();
    return () => {
      if (boundaryTimerId) window.clearTimeout(boundaryTimerId);
    };
  }, [activeLineIndex, config.globalOffset, engineRef, isPlaying, previewEnabled, songKey, stageLyrics]);
  const resolvedActiveIndex = previewEnabled
    ? previewIndex
    : (visualTrackChanged
      ? immediateVisualIndex
      : (clockActiveIndex >= 0 ? clockActiveIndex : immediateVisualIndex));
  const active = clamp(resolvedActiveIndex, 0, Math.max(0, stageLyrics.length - 1));
  const showPreviousLine = config.ktvShowPreviousLine === true;
  const openingTime = currentPlaybackTime;
  const showTitleCard = config.ktvShowTitleCard !== false && (previewEnabled || visualTrackChanged || (openingTime < 1.8 && active <= 0));
  const showTranslation = config.ktvShowTranslation !== false && config.showTranslation !== false;
  const showLyricIndex = config.ktvShowLyricIndex === true;
  const backdropMode = ['rich', 'cover', 'lyrics', 'minimal'].includes(config.ktvBackdrop) ? config.ktvBackdrop : 'rich';
  const motion = clamp(Number(config.ktvMotion ?? 1), 0.35, 1.8);
  const cameraZoom = clamp(Number(config.ktvCameraZoom ?? 0), 0, 1);
  const cameraTilt = clamp(Number(config.ktvCameraTilt ?? 0), -8, 8);
  const cameraShake = clamp(Number(config.ktvCameraShake ?? 0), 0, 1);
  const renderQuality = resolveRenderQuality(config, runtimeQuality);
  const songTemplate = config.ktvSongTemplates?.[String(songKey)] || '';
  const requestedPreset = ((PV_PRESETS[songTemplate] && !DISABLED_PV_PRESETS.has(songTemplate)) || songTemplate === 'multi')
    ? songTemplate
    : (config.ktvPreset || 'auto');
  const multiTemplate = requestedPreset === 'multi';
  const autoTemplate = requestedPreset === 'auto';
  let preset;
  if (requestedPreset !== 'auto' && PV_PRESETS[requestedPreset] && !DISABLED_PV_PRESETS.has(requestedPreset)) {
    preset = requestedPreset;
  } else if (multiTemplate) {
    // A multi-template edit changes on chapter boundaries rather than every
    // lyric row. Switching the whole stage on each line was visually noisy
    // and repeatedly rebuilt all preset-specific compositor styles.
    preset = resolvePreset({ ...config, ktvPreset: 'multi' }, songKey, themeColor, Math.floor(active / 4));
  } else {
    // The cover palette resolves asynchronously. Accept a refined colour only
    // during the opening beat, then lock this exact template for the rest of
    // the song so a late image decode never restyles a running verse.
    const playbackTime = engineRef?.current?.getCurrentTime?.() || 0;
    const canRefineOpening = previewEnabled || (playbackTime < 1.2 && activeLineIndex <= 0);
    const songChanged = autoPresetRef.current.songKey !== songKey || !autoPresetRef.current.preset;
    const colorRefined = autoPresetRef.current.themeColor !== themeColor;
    if (songChanged || (colorRefined && canRefineOpening)) {
      autoPresetRef.current = {
        songKey,
        themeColor,
        preset: resolvePreset({ ...config, ktvPreset: 'auto' }, songKey, themeColor, active)
      };
    }
    preset = autoPresetRef.current.preset;
  }
  const accent = resolveAccent(config, themeColor, preset, autoTemplate);
  // Light PV canvases need a dark idle face; all other templates use a near-
  // opaque light face. The live fill remains the preset accent, so word timing
  // stays visible without hiding unsung parts of the current line.
  const lightLyricSurface = ['blue-structure', 'paper-cut', 'girly-clouds', 'sweet-pink'].includes(preset);
  const lyricIdle = lightLyricSurface ? '#1c2030' : 'rgba(246,245,239,.98)';
  // Keep the optional pulse/spark pass limited to the presets that actually
  // benefit from it. The normal PV path uses one dedicated art scene and the
  // active lyric row, avoiding a second full-stage decorative system.
  const showRichDecor = renderQuality === 'rich'
    && ['blue-impact', 'kinetic-split', 'cyber-grunge', 'p5', 'crime-scene'].includes(preset);
  // Auto mode deliberately keeps the template's art direction, then blends
  // its native accent with the cover-derived colour. The result is stable for
  // a whole song but gives two albums in the same template distinct light and
  // beat details instead of a single recoloured background.
  const accentAlt = `color-mix(in hsl, ${accent} 68%, ${PV_PRESETS[preset]?.accent || '#7fd8ff'} 32%)`;
  const lineOpacityBase = PRESET_LINE_OPACITY[preset] || 0.32;

  useEffect(() => {
    const requestedQuality = config.ktvRenderQuality || 'auto';
    if (runtimeQualitySongRef.current !== songKey) {
      runtimeQualitySongRef.current = songKey;
      setRuntimeQuality(current => current === null ? current : null);
    }
    if (requestedQuality !== 'auto') {
      setRuntimeQuality(current => current === null ? current : null);
      return undefined;
    }
    if (!previewEnabled && !isPlaying) return undefined;
    // Sample compositor cadence only while PV is actually visible. Eight
    // frames slower than 34ms in a short window is a real missed-frame burst,
    // not an isolated GC pause. Once lowered, keep the tier for this song so
    // the stage never thrashes between visual budgets mid-verse.
    let frameId = 0;
    let lastFrameAt = performance.now();
    let sampleCount = 0;
    let slowFrames = 0;
    const observe = (now) => {
      const elapsed = now - lastFrameAt;
      lastFrameAt = now;
      if (!document.hidden) {
        sampleCount += 1;
        if (elapsed > 34) slowFrames += 1;
        else if (elapsed < 25 && slowFrames > 0) slowFrames -= 1;
        if (sampleCount >= 14 && slowFrames >= 8) {
          setRuntimeQuality(current => current === 'efficient' ? current : 'efficient');
          return;
        }
      }
      frameId = window.requestAnimationFrame(observe);
    };
    frameId = window.requestAnimationFrame(observe);
    return () => window.cancelAnimationFrame(frameId);
  }, [config.ktvRenderQuality, isPlaying, previewEnabled, songKey]);

  useEffect(() => {
    if (!previewEnabled) {
      previewOriginRef.current = 0;
      setPreviewIndex(0);
      return undefined;
    }
    previewOriginRef.current = performance.now();
    setPreviewIndex(0);
    let timer = null;
    const syncPreview = () => {
      const elapsed = ((performance.now() - previewOriginRef.current) / 1000) % PV_PREVIEW_CYCLE;
      const next = resolveVisualActiveIndex(PV_PREVIEW_LYRICS, elapsed, 0);
      setPreviewIndex(current => current === next ? current : next);
      const nextBoundaryIndex = next >= PV_PREVIEW_LYRICS.length - 1 ? 0 : next + 1;
      const nextBoundary = nextBoundaryIndex === 0 ? PV_PREVIEW_CYCLE : PV_PREVIEW_LYRICS[nextBoundaryIndex].time;
      const wait = Math.max(40, Math.min(4000, (nextBoundary - elapsed) * 1000 + 8));
      timer = window.setTimeout(syncPreview, wait);
    };
    syncPreview();
    return () => {
      if (timer) window.clearTimeout(timer);
    };
  }, [previewEnabled]);

  const lineRoleCounts = useMemo(() => {
    const counts = new Map();
    stageLyrics.forEach(line => {
      const normalized = normalizeRoleText(line?.text);
      if (normalized) counts.set(normalized, (counts.get(normalized) || 0) + 1);
    });
    return counts;
  }, [stageLyrics]);

  const models = useMemo(() => {
    if (!stageLyrics.length) return [];
    // Fly Me to the Moon uses a small camera window rather than a lyric wall:
    // two nearby lines on either side provide spatial context while distant
    // lyrics never enter the compositor.
    const offsets = preset === 'fly-me-to-the-moon'
      ? [-2, -1, 0, 1, 2]
      : showPreviousLine ? [-1, 0] : [0];
    return offsets.map(offset => {
      const index = active + offset;
      if (index < 0 || index >= stageLyrics.length) return null;
      const relation = offset === 0 ? 'active' : offset < 0 ? 'previous' : 'next';
      const scene = resolveScene(index, config.ktvComposition || 'auto', previewEnabled ? 'pv-preview' : songKey, stageLyrics[index]?.text);
      const act = resolveSongAct(index, stageLyrics.length);
      const role = resolveLineRole(stageLyrics[index], index, stageLyrics, lineRoleCounts);
      const sectionStart = isSectionStart(index, stageLyrics);
      const rawTokens = buildTokens(stageLyrics[index], stageLyrics[index + 1]);
      const grammar = resolveLineGrammar(config, preset, scene, stageLyrics[index], rawTokens, role);
      const revealMode = resolveRevealMode(config, stageLyrics[index], rawTokens, index, role, preset);
      const tokens = applyTokenChoreography(stageLyrics[index], rawTokens, revealMode);
      const theme = resolveLyricTheme(stageLyrics[index]?.text, tokens);
      const wordVariant = resolveWordVariant(config, preset, grammar.motionVariant, index, stageLyrics[index]);
      return {
        // Include the track identity so a same-timestamp first line from the
        // next song cannot reuse the previous DOM row and its mutable token
        // paint cache.
        key: lineKey(stageLyrics[index], index, previewEnabled ? 'pv-preview' : songKey),
        line: stageLyrics[index],
        tokens,
        theme,
        preset,
        index,
        relation,
        distance: offset,
        scene,
        act,
        role,
        sectionStart,
        revealMode,
        wordVariant,
        ...grammar,
        start: Number(stageLyrics[index].time) || 0,
        end: getLineEnd(stageLyrics[index], stageLyrics[index + 1])
      };
    }).filter(Boolean);
  }, [active, config.ktvComposition, config.ktvPresetPool, config.ktvTextEffect, lineRoleCounts, lyrics, previewEnabled, preset, showPreviousLine, songKey, stageLyrics]);
  const activeModel = models.find(model => model.relation === 'active');
  const activeScene = activeModel?.scene || 'poster';

  const register = useCallback((key, node, relation) => {
    if (!node) {
      lineNodes.current.delete(key);
      return;
    }
    const previous = lineNodes.current.get(key);
    const relationChanged = previous && previous.relation !== relation;
    const tokens = Array.from(node.querySelectorAll('.kpv-token'));
    lineNodes.current.set(key, {
      root: node,
      tokens,
      timings: tokens.map(token => ({
        start: Number(token.dataset.revealStart || token.dataset.start),
        end: Number(token.dataset.revealEnd || token.dataset.end)
      })),
      meter: node.querySelector('.kpv-meter > i'),
      fills: [],
      states: [],
      meterProgress: -1,
      finished: false,
      nextTokenIndex: 0,
      lastPaintTime: -Infinity,
      initialized: relationChanged ? false : Boolean(previous?.initialized),
      relation
    });
  }, []);

  useEffect(() => {
    // A new song must not inherit the previous track's analyser energy or
    // meter position. Resetting these mutable values at the track boundary
    // prevents a one-frame brightness/scale jump before the first new sample.
    audioPulseRef.current = { buffer: null, value: 0, lastSampleAt: 0, lastPainted: -1 };
    stageProgressRef.current = -1;
    if (stageRef.current) {
      stageRef.current.style.setProperty('--kpv-energy', '0');
      stageRef.current.style.setProperty('--kpv-phrase-progress', '0');
      stageRef.current.style.setProperty('--kpv-phrase-reveal', '0%');
      stageRef.current.style.setProperty('--kpv-trace-position', '8%');
      stageRef.current.style.setProperty('--kpv-trace-up-82', '8%');
      stageRef.current.style.setProperty('--kpv-trace-up-72', '7%');
      stageRef.current.style.setProperty('--kpv-trace-up-65', '9%');
    }
  }, [previewEnabled, songKey]);

  useEffect(() => {
    let lastLyricPaintAt = 0;
    let lastLyricClockTime = Number.NaN;
    let stalledLyricFrames = 0;
    let lastPvFrameAt = -Infinity;
    const paintToken = (refs, token, index, fill, animateFill = true) => {
      const nextFill = Math.round(fill * 1000) / 10;
      const state = fill >= 0.999 ? 'done' : fill > 0.001 ? 'live' : 'waiting';
      // Completed and queued glyphs are static. During a word sweep only the
      // currently sung token receives a style write, instead of repainting the
      // whole lyric line at 60fps.
      const stateChanged = refs.states[index] !== state || token.dataset.state !== state;
      const fillChanged = refs.fills[index] !== nextFill;
      const fillMode = animateFill ? 'continuous' : 'state-only';
      const modeChanged = refs.fillMode !== fillMode;
      if (!stateChanged && (!animateFill || (!fillChanged && !modeChanged))) return;
      refs.fills[index] = nextFill;
      refs.fillMode = fillMode;
      if (stateChanged) {
        refs.states[index] = state;
        token.dataset.state = state;
      }
      // Phrase and scan modes only need state transitions. Avoid writing two
      // CSS custom properties for every glyph on every clock tick when their
      // fill layer is hidden; letter mode keeps the continuous sweep.
      if (animateFill && (fillChanged || modeChanged)) {
        token.style.setProperty('--kpv-fill', `${nextFill}%`);
        token.style.setProperty('--kpv-fill-ratio', String(Math.round(fill * 1000) / 1000));
      }
    };

    const paintStateOnlyTokens = (refs, time) => {
      let cursor = refs.nextTokenIndex || 0;
      let firstLiveIndex = -1;
      while (cursor < refs.tokens.length) {
        const token = refs.tokens[cursor];
        const timing = refs.timings[cursor] || {};
        const start = timing.start;
        const end = timing.end;
        if (time < start) break;
        const fill = clamp((time - start) / Math.max(0.016, end - start));
        paintToken(refs, token, cursor, fill, false);
        if (fill < 0.999 && firstLiveIndex < 0) firstLiveIndex = cursor;
        cursor += 1;
      }
      // Keep the earliest in-progress token as the cursor so it transitions
      // to done on the next clock tick without rescanning already landed text.
      refs.nextTokenIndex = firstLiveIndex >= 0 ? firstLiveIndex : cursor;
    };

    const paintLetterTokens = (refs, time) => {
      let cursor = refs.nextTokenIndex || 0;
      while (cursor < refs.tokens.length) {
        const token = refs.tokens[cursor];
        const timing = refs.timings[cursor] || {};
        const start = timing.start;
        const end = timing.end;
        if (time < start) break;
        const fill = clamp((time - start) / Math.max(0.016, end - start));
        paintToken(refs, token, cursor, fill, true);
        if (fill < 0.999) break;
        cursor += 1;
      }
      refs.nextTokenIndex = cursor;
    };

    const updateAudioPulse = (now = performance.now()) => {
      const stage = stageRef.current;
      if (!stage) return;
      if (!isPlaying || config.ktvBeatReactive === false) {
        if (audioPulseRef.current.lastPainted !== 0) {
          audioPulseRef.current.lastPainted = 0;
          audioPulseRef.current.value = 0;
          stage.style.setProperty('--kpv-energy', '0');
        }
        return;
      }
      const pulse = audioPulseRef.current;
      // The lyric clock can tick at display refresh rate. Sample only the low
      // frequency bins at 12.5fps, then smooth the result; this makes shots
      // respond to kick/snare energy without adding a second render loop.
      const sampleInterval = renderQuality === 'efficient' ? 160 : renderQuality === 'balanced' ? 110 : 80;
      if (now - pulse.lastSampleAt < sampleInterval) return;
      pulse.lastSampleAt = now;
      const analyser = window.ichigoAnalyser;
      // Direct remote streams intentionally do not create a WebAudio analyser
      // (that would reintroduce CORS/MediaElementSource failures). Keep the
      // PV alive with a tiny clock-driven fallback so its background still
      // breathes instead of looking frozen when audio is analyser-less.
      if (!analyser?.getByteFrequencyData || !analyser.frequencyBinCount) {
        const beat = 0.08 + (Math.sin(now / 260 + active * 1.7) + 1) * 0.075;
        pulse.value = pulse.value * 0.72 + beat * 0.28;
        const painted = Math.round(pulse.value * 100) / 100;
        if (Math.abs(pulse.lastPainted - painted) >= 0.015) {
          pulse.lastPainted = painted;
          stage.style.setProperty('--kpv-energy', String(painted));
        }
        return;
      }
      if (!pulse.buffer || pulse.buffer.length !== analyser.frequencyBinCount) {
        pulse.buffer = new Uint8Array(analyser.frequencyBinCount);
      }
      analyser.getByteFrequencyData(pulse.buffer);
      const bins = Math.min(40, pulse.buffer.length);
      let total = 0;
      for (let index = 1; index < bins; index += 1) total += pulse.buffer[index];
      const target = clamp((total / Math.max(1, bins - 1) - 18) / 125);
      pulse.value = pulse.value * 0.7 + target * 0.3;
      const painted = Math.round(pulse.value * 100) / 100;
      if (Math.abs(pulse.lastPainted - painted) >= 0.02) {
        pulse.lastPainted = painted;
        stage.style.setProperty('--kpv-energy', String(painted));
      }
    };

    const update = (clockNow = performance.now()) => {
      // Hidden windows should not keep sampling the analyser or mutating CSS.
      // The shared lyric clock immediately paints the current frame on return.
      if (document.hidden) return;
      // The shared lyric clock runs at display refresh rate for the other
      // renderers. PV only needs a 30fps paint budget in balanced mode; this
      // keeps the CSS fill smooth while avoiding redundant DOM work on 60/120Hz
      // displays.
      const frameInterval = renderQuality === 'rich' ? 16 : renderQuality === 'efficient' ? 50 : 33;
      if (clockNow - lastPvFrameAt < frameInterval) return;
      lastPvFrameAt = clockNow;
      const time = previewEnabled
        ? (Math.max(0, (clockNow - (previewOriginRef.current || clockNow)) / 1000) % PV_PREVIEW_CYCLE)
        : (engineRef?.current?.getCurrentTime?.() || 0) + (Number(config.globalOffset) || 0);

      // A media element can remain logically "playing" while its currentTime
      // is frozen during a stalled network/decode interval. Freeze PV writes
      // until the media clock advances or the user seeks, instead of keeping
      // the compositor hot during the stall.
      if (!previewEnabled && isPlaying) {
        if (Number.isFinite(lastLyricClockTime) && Math.abs(time - lastLyricClockTime) < 0.0005) {
          stalledLyricFrames += 1;
          if (stalledLyricFrames >= 2) return;
        } else {
          stalledLyricFrames = 0;
        }
        lastLyricClockTime = time;
      } else {
        lastLyricClockTime = time;
        stalledLyricFrames = 0;
      }
      updateAudioPulse(clockNow);

      // Clip-path word fill remains visually continuous at 30fps, while
      // reducing style writes substantially on long timed lyrics. The shared
      // clock can still tick at display refresh rate for every other mode.
      const lyricPaintInterval = renderQuality === 'efficient' ? 50 : 33;
      const paintNow = clockNow;
      if (paintNow - lastLyricPaintAt < lyricPaintInterval) return;
      lastLyricPaintAt = paintNow;

      models.forEach((model) => {
        const refs = lineNodes.current.get(model.key);
        if (!refs) return;
        const activeLine = model.relation === 'active';
        if (!refs.initialized) {
          refs.initialized = true;
          refs.root.style.setProperty('--kpv-line-opacity', activeLine ? '1' : model.relation === 'previous' ? '.52' : '.28');
          refs.root.dataset.live = 'false';
          refs.tokens.forEach((token, index) => paintToken(refs, token, index, model.relation === 'previous' ? 1 : 0, model.revealMode === 'letter'));
        }
        if (!activeLine) return;

        const progress = clamp((time - model.start) / Math.max(0.08, model.end - model.start));
        if (stageRef.current && Math.abs(stageProgressRef.current - progress) >= 0.004) {
          stageProgressRef.current = progress;
          stageRef.current.style.setProperty('--kpv-phrase-progress', String(progress));
          stageRef.current.style.setProperty('--kpv-phrase-reveal', `${Math.round(progress * 1000) / 10}%`);
          stageRef.current.style.setProperty('--kpv-trace-position', `${Math.round((8 + progress * 84) * 1000) / 10}%`);
          stageRef.current.style.setProperty('--kpv-trace-up-82', `${Math.round((8 + progress * 82) * 1000) / 10}%`);
          stageRef.current.style.setProperty('--kpv-trace-up-72', `${Math.round((7 + progress * 72) * 1000) / 10}%`);
          stageRef.current.style.setProperty('--kpv-trace-up-65', `${Math.round((9 + progress * 65) * 1000) / 10}%`);
        }
        const isLive = time >= model.start && time < model.end;
        const liveValue = isLive ? 'true' : 'false';
        if (refs.root.dataset.live !== liveValue) refs.root.dataset.live = liveValue;
        if (time < refs.lastPaintTime - 0.05) {
          // A seek or a newly selected track can move the shared clock back.
          // Rewind the cursor once so state-only modes rebuild from the first
          // token instead of leaving earlier glyphs in their landed state.
          refs.nextTokenIndex = 0;
          refs.finished = false;
        }
        refs.lastPaintTime = time;
        // Once a line has fully landed, freeze its final token state until
        // the active-line boundary changes. This avoids scanning every glyph
        // during instrumental gaps while preserving seek-back correctness.
        if (time >= model.end) {
          if (!refs.finished) {
            refs.tokens.forEach((token, index) => paintToken(refs, token, index, 1, model.revealMode === 'letter'));
            if (refs.meter && refs.meterProgress !== 1) {
              refs.meterProgress = 1;
              refs.meter.style.transform = 'scaleX(1)';
            }
            refs.finished = true;
          }
          return;
        }
        refs.finished = false;
        if (refs.meter && Math.abs(refs.meterProgress - progress) >= 0.002) {
          refs.meterProgress = progress;
          refs.meter.style.transform = `scaleX(${progress})`;
        }

        if (model.revealMode === 'letter') {
          paintLetterTokens(refs, time);
        } else {
          paintStateOnlyTokens(refs, time);
        }
      });
    };

    update();
    // A paused PV only needs the one synchronous paint above. Keeping it on
    // the shared 60fps clock while paused wastes work and can leave stale
    // compositor writes running behind the player controls.
    if (!previewEnabled && !isPlaying) return undefined;
    if (!previewEnabled) return subscribeLyricClock(update);
    let frameId = 0;
    const previewFrame = (now) => {
      if (document.hidden) {
        frameId = 0;
        return;
      }
      update(now);
      frameId = requestAnimationFrame(previewFrame);
    };
    const handleVisibilityChange = () => {
      if (document.hidden) {
        if (frameId) cancelAnimationFrame(frameId);
        frameId = 0;
        return;
      }
      if (!frameId) frameId = requestAnimationFrame(previewFrame);
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    if (!document.hidden) frameId = requestAnimationFrame(previewFrame);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      if (frameId) cancelAnimationFrame(frameId);
    };
  }, [config.globalOffset, config.ktvBeatReactive, engineRef, isPlaying, lineOpacityBase, models, previewEnabled, renderQuality]);

  return (
    <section
      ref={stageRef}
      className={`kpv-stage kpv-preset--${preset}${isPlaying || previewEnabled ? '' : ' kpv-stage--paused'}${previewEnabled ? ' kpv-stage--preview' : ''}`}
      data-scene={activeScene}
      data-act={activeModel?.act || 'intro'}
      data-auto-template={autoTemplate ? 'true' : 'false'}
      data-hook={activeModel?.role === 'hook' ? 'true' : 'false'}
      data-section={activeModel?.sectionStart ? 'start' : 'continue'}
      data-line-key={activeModel?.key || ''}
      data-quality={renderQuality}
      style={{ '--kpv-accent': accent, '--kpv-accent-alt': accentAlt, '--kpv-motion': motion, '--kpv-energy': 0, '--kpv-lines-opacity': lineOpacityBase, '--kpv-token-idle': lyricIdle, '--kpv-token-live': 'var(--kpv-accent)', '--kpv-phrase-progress': 0, '--kpv-phrase-reveal': '0%', '--kpv-camera-zoom': 1 + cameraZoom * 0.08, '--kpv-camera-tilt': `${cameraTilt}deg`, '--kpv-camera-shake': cameraShake }}
      aria-label="KTV text PV"
    >
      <div className="kpv-camera">
        <div className={`kpv-background-camera${cameraShake > 0 ? ' kpv-camera--shake' : ''}`}>
          <div className="kpv-grain" aria-hidden="true" />
           {showTitleCard && <div key={previewEnabled ? 'pv-preview' : (songKey || 'current-song')} className="kpv-title-card" aria-hidden="true"><i>ICHIGOMUSIC / TEXT PV</i><b>{previewEnabled ? 'PV TEMPLATE PREVIEW' : (songTitle || 'NOW PLAYING')}</b><span>{previewEnabled ? 'LIVE TYPE COMPOSITOR' : (songArtist || 'ICHIGOMUSIC')}</span></div>}
          {previewEnabled && <div className="kpv-preview-mark" aria-hidden="true">PV TEMPLATE PREVIEW 闂?LIVE TYPE</div>}
          {config.ktvUseCoverTexture !== false && pvCoverUrl && <div className="kpv-coverwash" aria-hidden="true" style={{ backgroundImage: `url("${pvCoverUrl}")` }} />}
          {config.ktvUseCoverTexture !== false && pvCoverUrl && <div className="kpv-cover-cel" aria-hidden="true" style={{ backgroundImage: `url("${pvCoverUrl}")` }}><i /></div>}
          {preset === 'fly-me-to-the-moon' ? <FlyMoonSpatialCloud songKey={songKey} activeIndex={active} coverUrl={config.ktvUseCoverTexture !== false ? pvCoverUrl : ''} renderQuality={renderQuality} /> : <KtvReactiveBackdrop key={'backdrop-' + (activeModel?.key || 'empty') + '-' + backdropMode} model={activeModel} coverUrl={config.ktvUseCoverTexture !== false ? pvCoverUrl : ''} mode={backdropMode} renderQuality={renderQuality} />}
          {renderActivePvScene(preset)}
          {showRichDecor && <div className="kpv-radial-pulse" aria-hidden="true"><i /><i /><i /></div>}
          {showRichDecor && <div className="kpv-sparks" aria-hidden="true"><i /><i /><i /><i /><i /><i /><i /><i /></div>}
          {(['blue-structure', 'cyber-grunge'].includes(preset)) && <div className="kpv-preset-motif" aria-hidden="true">
            <i /><i /><i /><i /><i /><i /><i /><i />
            <div className="kpv-blue-structure-scene">
              <div className="kpv-structure-blocks"><i /><i /><i /><i /><i /><i /><i /></div>
              <div className="kpv-structure-rays"><i /><i /><i /><i /><i /><i /><i /><i /></div>
              <div className="kpv-structure-rings"><b /><b /><b /><b /><b /></div>
              <div className="kpv-structure-links"><i /><i /><i /><i /><i /></div>
            </div>
            <div className="kpv-cyber-scene">
              <div className="kpv-cyber-monitors"><i /><i /><i /><i /><i /></div>
              <div className="kpv-cyber-debris"><i /><i /><i /><i /><i /><i /></div>
              <div className="kpv-cyber-bars"><b /><b /><b /><b /></div>
            </div>
            <div className="kpv-blue-formulas"><b>E² = (pc)² + (mc²)²</b><b>dx · dp ≥ h / 2</b><b>div E = ρ / ε₀</b><b>curl E = −dB / dt</b><b>d²u / dt² = c² ∇²u</b><b>F = ma / λ</b><b>ψ(x,t) = A e^(i(kx−ωt))</b><b>λ = h / p</b><b>∮ E · ds = 0</b></div>
            <div className="kpv-cyber-noise"><b>SYS // NULL_04</b><b>ERR 0x7F // TRACE</b><b>NO SIGNAL // RETRY</b><b>MEM DUMP // LOST</b></div>
            <div className="kpv-preset-marks"><b>/01</b><b>///</b><b>NO.07</b><b>Δ</b><b>00:00</b><b>TRACE</b></div>
          </div>}
        </div>
              {/* Theme typography shares the lyric camera, but remains one z-layer
            below the complete active line. */}
        <KtvThemeLayer key={`theme-${activeModel?.key || 'empty'}`} model={activeModel} />
      {models.map(model => (
        <KtvLine
          key={model.key}
          model={model}
          fontPx={Math.min(104, fontPx * 1.42)}
          fontStack={fontStack}
          showLyricIndex={showLyricIndex}
          presetLabel={PV_PRESETS[preset].label}
           renderQuality={renderQuality}
           register={register}
           config={config}
         />
      ))}
      </div>

      {/* Keep the translation in one stage-level layer. It must not inherit
          lyric-line transforms, scene layouts, or the moving camera. */}
      {(() => {
        const fixedTranslation = showTranslation && activeModel?.line?.translation
          ? String(activeModel.line.translation)
          : '';
        return (
          <div
            key={activeModel?.key || 'kpv-translation-empty'}
            className={`kpv-fixed-translation${fixedTranslation ? '' : ' kpv-fixed-translation--empty'}`}
            style={{ fontSize: `${Math.max(18, Math.min(30, translationPx * 1.35))}px`, fontFamily: fontStack }}
            aria-live="polite"
            aria-hidden={!fixedTranslation}
          >
            <span className="kpv-fixed-translation__text">{fixedTranslation}</span>
          </div>
        );
      })()}
      {KTV_PV_STYLE_ELEMENTS}
      {KTV_PV_TRANSLATION_GUARD}
      {KTV_PV_RESTORED_MOTION}
      {KTV_PV_REFERENCE_LAYERS}
      {KTV_PV_PERFORMANCE_GUARD}
      {KTV_PV_FOREGROUND_DIRECTIONS}
      {KTV_PV_SCENE_LENSES}
      {KTV_PV_TEMPLATE_MOTION}
      {KTV_PV_PALETTE_REFINEMENTS}
      {KTV_PV_WORD_RENDERERS}
      {KTV_PV_VARIANTS_AND_BACKDROP}
      {KTV_PV_TOKEN_VARIATIONS}
      {KTV_PV_OPEN_COMPOSITIONS}
      {KTV_PV_FINAL_THEME_REFINEMENTS}
      {KTV_PV_GEOMETRIC_FLY_REFINEMENTS}
      {KTV_PV_ALIGNMENT_GUARD}
    </section>
  );
}
